INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 2 AND "number" = 5), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"{مِنْ رَبِّهِمْ} [٥] ليس بوقف منصوص عليه فلا يحسن تعمده، فإن وقف عليه واقف جاز قاله العماني.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
