INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 2 AND "number" = 6), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"ليس بوقف؛ لأنَّ «أم لم تنذرهم» عطف عليه؛ لأنَّ ما قبل «أم» المتصلة وما بعدها لا يستغنى بأحدهما عن الآخر، وهما بمنزلة حرف واحد","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 2 AND "number" = 7), 0, 'BOOKS', 'APPROVED', '{"ruling":"صالح","explanation":"صالح؛ إن قدرت الختم على القلوب خاصة، وإن قدرته بمعنى: «وختم على سمعهم» أيضًا لم يكن على «قلوبهم» وقفًا؛ لأنَّ الثاني معطوف على الأول","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 2 AND "number" = 8), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"إن جعل ما بعده استئنافًا بيانيًّا؛ كأنَّ قائلًا يقول: ما بالهم قالوا آمنا ويظهرون الإيمان وما هم بمؤمنين؟! فقيل: «يخادعون الله».","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 2 AND "number" = 9), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"لعطف الجملتين المتفقتين مع ابتداء النفي، ومن قرأ: «وما يخدعون» بغير ألف بعد الخاء كان أحسن، وقرأ أبو طالوت عبد السلام بن شداد (١): {وما يَخْدَعُونَ إِلَّا أَنْفُسَهُمْ}، بضم الياء وسكون الخاء، ورفع «أنفسهم» بدلًا من الضمير في «يُخْدعون»؛ كأنه قال: وما يخدعون إلَّا أنفسهم، أو بفعل مضمر، كأنه قال: وما يخدعون إلا نخدعهم أنفسهم. ولا يجوز الوقف على «أنفسهم»؛ لأنَّ ما بعد «هم» جملة حالية من فاعل، «وما يخادعون»، أي: وما يخادعون إلَّا أنفسهم غير شاعرين بذلك؛ إذ لو شعروا بذلك ما خادعوا الله ورسوله والمؤمنين. وحذف مفعول «يشعرون» للعلم به، أي: وما يشعرون وبال خداعهم.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
