INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 2 AND "number" = 14), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"ليس بوقف؛ لأنَّ الوقف عليه يوهم غير المعنى المراد، ويثبت لهم الإيمان، وإنما سمَّوهُ النطق باللسان إيمانًا، وقلوبهم معرضة، تورية منهم وإيهامًا، والله سبحانه وتعالى أطلع نبيه على حقيقة ضمائرهم، وأعلمه أنَّ إظهارهم للإيمان لا حقيقة له، وإنه كان استهزاءً منهم","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 2 AND "number" = 15), 0, 'BOOKS', 'APPROVED', '{"ruling":"صالح","explanation":"صالح؛ ووصله أبين لمعنى المجازاة؛ إذ لا يجوز على الله الاستهزاء، وظهور المعنى في قول الله: «الله يستهزئ بهم» مع اتصاله بما قبله يظهر في حال الابتداء بضرب من الاستنباط، وفي حال الاتصال يظهر المعنى من فحوى الكلام، كذا وجه أبو حاتم، وأما وجه الوقف على «مستهزءون» فإنه معلوم أنَّ الله لا يجوز عليه معنى الاستهزاء، فإذا كان ذلك معلومًا عرف منه معنى المجازاة، أي: يجازيهم جزاء الاستهزاء بهم. وقيل معنى: «الله يستهزئ بهم» بجهلهم، وبهذا المعنى يكون الوقف على «يعمهون» كافيًا، وعلى الأول يكون تامًّا. انظر: النكزاوي","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
