INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 2 AND "number" = 17), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"لأنهما من جملة ما ضربه الله مثلًا للمنافقين بالمستوقد نارًا، وبأصحاب الصيب، والفائدة لا تحصل إلَّا بجملة المثل","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 2 AND "number" = 18), 0, 'BOOKS', 'APPROVED', '{"ruling":"صالح","explanation":"وقيل: لا يوقف عليه؛ لأنه لا يتم الكلام إلَّا بما بعده؛ لأنَّ قوله: «أو كصيب» معطوف على «كمثل الذي استوقد نارًا»، أو كمثل أصحاب صيب، فـ «أو» للتخيير، أي: أبحناكم أن تشبهوا هؤلاء المنافقين بأحد هذين الشيئين أو بهما معًا، وليست للشك؛ لأنه لا يجوز على الله تعالى","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 2 AND "number" = 19), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"لأنَّ قوله: {فِيهِ ظُلُمَاتٌ وَرَعْدٌ وَبَرْقٌ}، من صفة الصيب، وكذا «من الصواعق»؛ لأنَّ «حذر» مفعول لأجله، أو منصوب بـ «يجعلون»، وإن جعل «يجعلون» خبر مبتدأ محذوف، أي: هم يجعلون، حسُن الوقف على «برق»","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
