INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 2 AND "number" = 24), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"لأنَّ «فاتقوا» جواب الشرط،، وقوله: «ولن تفعلوا» معترضة بين الشرط وجزائه، وحذف مفعول «لم تفعلوا ولن تفعلوا» اختصارًا، والتقدير: فإن لم تفعلوا الإتيان بسورة من مثله، ولن تفعلوا الإتيان بسورة من مثله. والوقف على «النار» لا يجوز؛ لأن التي صفة لها.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
