INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 2 AND "number" = 25), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"إن جعلت الجملة بعدها مستأنفة؛ كأنه قيل: لما وصفت الجنات ما حالها؟ فقيل: كلما رزقوا قالوا؛ فليس لها محل من الإعراب، وقيل: محلها رفع، أي: هي كلما ... ، وقيل: ومحلها نصب على الحال، وصاحبها إما «الذين آمنوا»، وإما «جنات»، وجاز ذلك وإن كانت نكرة؛ لأنها تخصصت بالصفة، وعلى هذين تكون حالًا مقدرة؛ لأنَّ وقت البشارة بالجنات لم يكونوا مرزوقين ذلك، وقيل: صفة لـ «جنات» أيضًا، وعلى كون الجملة حالًا أو صفة لا يكون حسنًا.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
