INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 2 AND "number" = 61), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"غير تام؛ لأنَّ «أتستبدلون» الآية فيها جملتان: الأولى من كلام الله لبني إسرائيل على جهة التوبيخ فيما سألوه، وقيل: من كلام موسى؛ وذلك أنه غضب لما سألوه هذا، فقال: «أتستبدلون الذي هو أدنى بالذي هو خير»، والثانية: وهي «اهبطوا مصرًا» من كلام الله، وهذا هو المشهور، وعليه فيكون الوقف على {خَيْرٌ} [٦١] تامًّا؛ لأنهما كلامان، ومن جعلهما كلامًا واحدًا كان الوصل أولى.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
