VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 2 AND "number" = 73), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"والأولى وصله؛ لأن في الكلام حذفًا، أي: اضربوه يحيى، أو فضرب فحيي، ثم وقع التشبيه في الإحياء المقدر، أي: مثل هذا الإحياء للقتيل يحيي الله الموتى، وإن جعل ما بعده مستأنفًا، وأن الآيات غير إحياء الموتى، وأن المعجزة في الإحياء، لا في قول الميت: قتلني فلان؛ فموضع الحجة غير موضع المعجزة، وقول الميت حق لا يحتاج إلى يمين، وعلى هذا يكون كافيًا.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
