VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 2 AND "number" = 183), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"؛ لأنه رأس آية، وليس بحسن؛ لأن ما بعده متعلق بـ «كتب»؛ لأن «أيامًا» منصوب على الظرف، أي: كتب عليكم الصيام في أيام معدودات؛ فلا يفصل بين الظرف وبين ما عمل فيه من الفعل، وقيل: منصوب؛ على أنه مفعول ثان لـ «كتب»، أي: كتب عليكم أن تصوموا أيامًا معدودات.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
