INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 2 AND "number" = 196), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"لمن رفع و «العمرةُ» على الاستئناف، فلا تكون العمرة واجبة، وبها قرأ الشعبي (١) وعامر (٢)، وتأولها أهل العلم بأن الله أمر بتمام الحج إلى انتهاء مناسكه، ثم استأنف الأخبار بأن العمرة لله؛ ليدل على كثرة ثوابها، وللترغيب في فعلها، وليس بوقف لمن نصبها عطفًا على «الحج»، فتكون داخلة في الوجوب وبهذه القراءة قرأ العامة (٣)","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 2 AND "number" = 197), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"يبني الوقف على «فسوقٌ»، ووصله على اختلاف القراء والمعربين في رفع «رفثٌ» وما بعده، فمن قرأ برفعهما والتنوين وفتح «جدالَ»، وبها قرأ أبو عمرو وابن كثير (١)، فوقفه على «فسوق» تام، ولا يوقف على شيء قبله، ثم يبتدئ «ولا جدال في الحج»، وليس «فسوق» بوقف لمن نصب الثلاثة، وهي قراءة الباقين (٢)، واختلف في رفع «رفث»، و «فسوق»، فقيل بالابتداء، والخبر محذوف تقديره: كائن أو مستقر في الحج، أو رفعهما على أن «لا» بمعنى: ليس، والخبر محذوف أيضًا، ففي «الحج» على الأول خبر ليس، وعلى الثاني خبر المبتدأ. وعليهما الوقف على {فُسُوقَ} [١٩٧] كاف، ومن نصب الثلاثة لم يفصل بوقف بينهما.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
