VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 2 AND "number" = 243), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"{حَذَرَ الْمَوْتِ} [٢٤٣] ليس بوقف؛ لوجود الفاء، وفي الحديث: «إذا سمعتم أن الوباء بأرض فلا تقدموا عليها، وإن وقع بأرض وأنتم بها فلا تخرجوا منها فرارًا منه» (١)، وفُهِم من قوله: «فرارًا منه» أنه لو كان الخروج لا على وجه الفرار، بل لحاجة فإنه لا يكره، وهذه الآية نزلت في قوم فروا من","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
