INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 2 AND "number" = 281), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"على قراءة أبي عمرو و «تَرجِعون» ببناء الفعل للفاعل بفتح التاء وكسر الجيم، و «توفى» مبني للمفعول بلا خلاف، فحسن الفصل بالوقف؛ لاختلاف لفظ الفعلين في البناء، وأما على قراءة الباقين: «تُرجَعون» ببناء الفعل للمفعول موافقة لـ «توفي»، فالأحسن الجمع بينهما بالوصل؛ لأن الفعلين على بناء واحد","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
