INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 2 AND "number" = 283), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"كاف؛ للابتداء بالشرط، واستئناف معنى آخر، ورسموا «اؤتمن» بواو؛ لأنه فعل مبني لما لم يسم فاعله، فيبتدأ به بضم الهمزة؛ لأنها ألف افتعل، وكان أصله: اأتمن، جعلت الهمزة الساكنة واوًا؛ لانضمام ما قبلها، فإن قيل: لِمَ صارت ألف ما لم يسم فاعله مضمومة؟ فقل: لأن فعل ما لم يسم فاعله يقتضي اثنين فاعلًا ومفعولًا، وذلك أنك إذا قلت: ضرب -دل الفعل على ضارب ومضروب، فضموا أوله؛ لتكون الضمة دالة على اثنين، أو يقال: إذا ابتدئ بالهمز الساكن -فإنه يكتب بحسب حركة ما قبله أولًا، أو وسطًا، أو آخر، نحو: «ائذن لي»، و «اؤتمن»، و «البأساء»، ومثله «ابتلى» و «اضطر».","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 2 AND "number" = 284), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"كاف، ومثله «به الله» إن رفع ما بعده على الاستئناف، أي: فهو يغفر، وليس بوقف إن جزم عطفًا على «يحاسبكم» فلا يفصل بينهما بالوقف.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 2 AND "number" = 285), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"تام، إن رفع «والمؤمنون» بالفعلية عطفًا على الرسول، ويدل لصحة هذا قراءة أمير المؤمنين علي بن أبي طالب: «وآمن المؤمنون» (١)، فأظهر الفعل، ويكون قوله: «كل آمن» مبتدأ وخبر يدل على أن جميع من ذكر «آمن» بمن ذكر، أو «المؤمنون» مبتدأ أول، و «كل» مبتدأ ثانٍ، و «آمن» خبر عن «كل»، وهذا المبتدأ وخبره خبر الأول، والرابط محذوف تقديره: منهم، وكان الوقف على «من ربه حسنًا»؛ لاستئناف ما بعده، والوجه كونها للعطف؛ ليدخل المؤمنون فيما دخل فيه الرسول من الإيمان بالله وملائكته وكتبه ورسله، بخلاف ما لو جعلت للاستئناف، فيكون الوصف للمؤمنين خاصة بأنهم آمنوا بالله وملائكته وكتبه ورسله دون الرسول، والأولى أن نصف الرسول والمؤمنين بأنهم آمنوا بسائر هذه المذكورات.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
