INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 3 AND "number" = 7), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"لأنَّ قوله: «منه آيات» متعلق به كتعلق الصفة بالموصوف، و «آيات محكمات» متعلق بـ «منه» على معنى: من الكتاب آيات محكمات، ومنه أخر متشابهات، ولو جاز هذا الوقف لجاز أن يقف على قوله: «ومن قوم موسى»، ثم يبتدئ «أمة يهدون بالحق»، ولا يقول هذا أحد؛ لأنهم يشترطون لصحة الوقف صحة الوقف على نظير ذلك الموضع، ونقل بعضهم أنَّ الوقف عند نافع على «منه»، ولم يذكر له وجهًا، ووجهه -والله أعلم- إنه جعل الضمير في «منه» كناية عن الله، أي: هو الذي أنزل عليك الكتاب من عنده، فيكون «منه» بمعنى: من عنده، ثم يبتدئ «آيات محكمات»، أي: هو آيات محكمات","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
