VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 3 AND "number" = 13), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"لمن رفع «فئة» بالابتداء (١)، وسوغ الابتداء بها التفصيل، وثَمَّ صفة محذوفة تقديرها: فئة مؤمنة تقاتل في سبيل الله، وأخرى كافرة تقاتل في سبيل الطاغوت، فحذف من الجملة الأولى ما أثبت مقابله في الجملة الثانية، ومن الثانية ما أثبت مقابله في الأولى، وهو من النوع المسمى بالاحتباك من أنواع البديع، وهي قراءة العامة (٢)","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
