VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 3 AND "number" = 21), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"لمن قرأ: «ويقاتلون» بألف بعد القاف؛ لعدول المعنى عن قوله: «ويقتلون» بغير ألف، وليس بوقف لمن قرأ: «ويقتلون» بغير ألف (2)؛ لفصله بين اسم «إنَّ» وخبرها، وقوله: «فبشرهم» في موضع خبر إن، وإن جعل خبر إن «أولئك الذين حبطت أعمالهم» -فلا يوقف على «أليم»، ولا على «الناس» للعلة المذكورة.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
