VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 3 AND "number" = 33), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"من حيث كونه رأس آية، وليس بمنصوص عليه؛ لأنَّ «ذرية» حال من «اصطفى»، أي: اصطفاهم حال كونهم ذرية بعضها من بعض، أو بدل من «آدم» وما عطف عليه على قول من يطلق الذرية على الآباء والأبناء، فلا يفصل بين الحال وذيها، ولا بين البدل والمبدل منه، فإن نصبت «ذرية» على المدح كان الوقف على «العالمين» كافيًا","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
