INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 3 AND "number" = 37), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"عند من خفف «وكفّلها»؛ لأنَّ الكلام منقطع عن الأول بتبدل فاعله؛ فإنَّ فاعل المخفف «زكريا»، وفاعل المشدد ضمير اسم الرب عزَّ وجلَّ، أي: وكفلها الله زكريا، وليس بوقف لمن شدد؛ لأنَّ الفعلين معًا لله تعالى، أي: أنبتها الله نباتًا حسنًا، وكفلها الله زكريا، وبها قرأ حمزة، والكسائي، وعاصم","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
