INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 3 AND "number" = 45), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"جائز، ويبتدئ اسمه «المسيح» بكسر الهمزة، ومثله «عيسى ابن مريم» إن جعل «عيسى» خبر مبتدأ محذوف، أي: هو عيسى، وليس بوقف إن جعل اسمه المجموع من قوله: «المسيح عيسى ابن مريم» كما في (الكشاف)، أو جعل «عيسى» بدلًا من المسيح، أو عطف بيان، و «ابن مريم» صفة لـ «عيسى».","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
