INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 3 AND "number" = 48), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"حسن إن نصب «ورسولًا» بمقدر، أي: ونجعله رسولًا، وليس بوقف لمن عطفه على «وجيهًا»، فيكون حالًا، أي: ومعلمًا الكتاب، وهو ضعيف؛ لطول الفصل بين المتعاطفين، وكذا على قراءة البزي، و «رسولٍ» بالجر عطفًا على «بكلمة منه»، أي: يبشرك بكلمة منه ورسول؛ لبعد المعطوف عليه والمعطوف","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 3 AND "number" = 49), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"كاف لمن قرأ: «إني أخلق» بكسر الهمزة، وهو نافع؛ على الاستئناف، أو على التفسير، فسر بهذه الجملة قوله: «بآية» كأنَّ قائلًا قال: وما الآية؟ فقال: إني أخلق، ونظيرها يأتي في قوله: {إِن مَثَلَ عِيسَى عِنْدَ اللَّهِ} [٥٩]، فجملة «خلقه» مفسرة للمثل، وكما في قوله: {وَعَدَ اللَّهُ الَّذِينَ آَمَنُوا وَعَمِلُوا الصَّالِحَاتِ} [المائدة: ٩]، ثم فسّر الوعد بقوله: {لَهُمْ مَغْفِرَةٌ} [المائدة: ٩]، فالاستئناف يؤتى به تفسيرًا لما قبله، وليس بوقف لمن قرأ بفتحها بدلًا من «أني قد جئتكم»، أو جعله في موضع خفض بدلًا من آية؛ بدل كل من كل إن أريد بالآية الجنس، أو جعلت خبر مبتدأ محذوف، أي: هي أني؛ فقوله: «أني» يجوز أن يكون في موضع رفع، أو نصب، أو جر، على اختلاف المعنى","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
