VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 3 AND "number" = 55), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"ومثله «ورافعك إليَّ»، وليس منصوصًا عليهما، والأولى وصلهما، وقيل: هو من المقدم والمؤخر، أي: رافعك إليَّ حيًّا، ومتوفيك","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
