INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 3 AND "number" = 59), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"{كَمَثَلِ آَدَمَ} [٥٩] حسن، وليس بتام، ولا كاف؛ لأنَّ «خلقه من تراب» تفسير للمثل، وهو متعلق به، فلا يقطع منه، وقال يعقوب: تام، و «خلقه من تراب» مستأنف، وإنما لم يكن خلقه متصلًا به؛ لأنَّ الإعلام لا يتصل بها الماضي، فلا تقول: مررت بزيد قام؛ لأنَّ قام لا يكون صفة لزيد ولا حالًا؛ لأنه قد وقع وانقطع، فإن أضمرت في الكلام قد جاز أن يتصل الماضي بالإعلام؛ لأنَّ الجمل بعد المعارف أحوال، وفي جملة «خلقه من تراب» وجهان: أظهرهما: أنها مفسرة لوجه التشبيه، فلا محل لها من الإعراب، والثاني: أنها في محل نصب على الحال من «آدم»، و «قد» معه مقدرة؛ لتقربه من الحال؛ والعامل فيها معنى التشبيه والضمير في «خلقه» عائد على «آدم»، لا على «عيسى»؛ لفساد المعنى.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 3 AND "number" = 60), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"أي: الذي أنبأك به في قصة عيسى الحق من ربك، أو هو الحق من ربك، أو أمر عيسى فهو خبر مبتدأ محذوف.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
