INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 3 AND "number" = 118), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"؛ لأنَّ جملة «لا يألونكم خبالًا» مفسرة لحال البطانة الكافرة، والتقييد بالوصف يؤذن بجواز الاتخاذ عند انتفائهما، وقد عتب عمر أبا موسى الأشعري على استكتابه ذميًّا، وتلا هذه الآية عليه، وقد قيل لعمر في كاتب يجيد من نصارى الحيرة: ألا يكتب عنك؟ فقال: إذًا أتخذ بطانة سوء؛ لأنَّه ينبغي استحضار ما جبلوا عليه من بعضنا، وتكذيب نبينا، وإنهم لو قدروا علينا لاستولوا على دمائنا، وما أحسن قول الطرطوشي (2) لما دخل على الخليفة بمصر، وكان من الفاطميين، ورآه سلَّم قياده لوزيره الراهب، ونفذ كلمته المشئومة حتى في الطرطوشي، ورآه مغضبًا عليه، فأنشده:_________","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
