INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 3 AND "number" = 124), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"و «بلى» وما بعدها جواب للنفي السابق الذي دخلت عليه ألف الاستفهام، وما بعد «بلى» في صلته فلا يفصل بينهما، ولا وقف من قوله: «بلى» إلى «مسومين»، فلا يوقف على «فورهم»، ولا على «هذا»؛ لأنَّ جواب الشرط لم يأت بعد وهو «يمددكم»، فلا يفصل بين الشرط وجوابه بالوقف","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
