INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 3 AND "number" = 126), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"لأنه رأس آية، والأولى وصله؛ لأنَّ لام كي في قوله: «ليقطع» متعلقة بما قبلها بقوله: «ولقد نصركم»، أي: ولقد نصركم الله ببدر؛ ليقطع طرفًا من الذين كفروا، وقيل معناه: إنَّما وقع التأييد من الله تعالى في إمدادكم بالملائكة؛ ليقطع طرفًا من الذين كفروا، فعلى كل حال اللام متعلقة بما قبلها، فلا يفصل بينها وبين ما قبلها بالوقف","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 3 AND "number" = 127), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"إن جعل «أو يتوب عليهم» عطفًا على شيء، أي: ليس لك من الأمر شيء، أو من أن يتوب عليهم، فليس منصوبًا بما قبله، أو إنَّما كان تامًّا؛ لاختلاف نزول الآيتين في غزوتين؛ لأنَّ من أوَّل القصة إلى «خائبين» نزل في غزوة بدر، ومن قوله: «ليس لك من الأمر شيء» إلى «ظالمون» نزل في غزوة أحد، وبينهما مدة، روي عن أنس بن مالك: أنه قال: لما كان يوم أحد كسرت رباعية النبي - صلى الله عليه وسلم -، وشج وجهه، فجعل الدم يسيل على وجهه، ورسول الله - صلى الله عليه وسلم - يمسح الدم عن وجهه، وهو يقول: «كيف يفلح قوم خضبوا وجه نبيهم بالدم وهو يدعوهم إلى الله؟!»، فأنزل الله: «ليس لك من الأمر شيء» (١)","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
