INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 3 AND "number" = 142), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"تام عند نافع، وخولف؛ لأنَّ ما بعده متعلق به؛ لأنَّ الله أراد أن يعلمنا أن الطمع في دخول الجنة مع تضييع الجهاد، وغيره -هو الطمع الكاذب، والظن الفاسد، فقال: «أم حسبتم» الآية، أي: لا تدخلون الجنة إلَّا بوجود الجهاد منكم، والمصابرة عليه، وبفعل الطاعات، فعلى هذا لا معنى للوقف؛ لأنَّ فائدة الكلام فيما بعده","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
