VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 3 AND "number" = 156), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"تام عند الأخفش؛ لأنه آخر كلام المنافقين، واللام في «ليجعل» متعلقة بمحذوف، أي: لا تكونوا كهؤلاء؛ ليجعل الله ذلك حسرة في قلوبهم دونكم، وقدّره الزمخشري: لا تكونوا مثلهم في النطق بذلك القول واعتقاده ليجعل، وليس بوقف إن علقت بـ «قالوا»، أي: أنهم لم يقولوا لجعل الحسرة، إنما قالوا ذلك لعلة، فصار مآل ذلك إلى الحسرة والندامة","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
