INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 3 AND "number" = 169), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"عند أبي حاتم، وتام عند محمد بن عيسى؛ لأنَّ «بل» بعد «أمواتًا» ليست عاطفة، ولو كانت عاطفة لاختل المعنى، وتقدير الكلام: بل هم أحياء، وهو عطف جملة على جملة، وهو في حكم الاستئناف.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
