INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 3 AND "number" = 171), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"{وَفَضْلٍ} [١٧١] تام على قراءة من كسر همزة «إنَّ» على الاستئناف، وبها قرأ الكسائي، وليس بوقف على قراءة من فتحها (١)؛ عطفًا على ما قبلها، والتقدير: يستبشرون بنعمة من الله وفضل، وبأنَّ الله لا يضيع، وعلى هذا فلا يوقف على «وفضل»؛ لعطفه على ما قبله.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 3 AND "number" = 172), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"{أَصَابَهُمُ الْقَرْحُ} [١٧٢] حسن إن جعل «الذين استجابوا» نعت المؤمنين، أو نصب على المدح، وليس بوقف إن جعل ذلك مبتدأ، و «للذين أحسنوا منهم واتقوا» خبرًا؛ لأنه لا يفصل بين المبتدأ والخبر بالوقف، يرتفع «أجر عظيم» بقوله: «للذين أحسنوا».","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
