INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 3 AND "number" = 175), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"{يُخَوِّفُ أَوْلِيَاءَهُ} [١٧٥] كاف، وتام، عند أبي حاتم، قال: لأنَّ المعنى: يخوف الناس أولياءه، أو يخوفونكم أولياءه، أو بأوليائه، وقال غيره: بل الوقف على قوله: «فلا تخافوهم»، وقال نافع: بل الوقف_________(١) وقرأ الباقون بفتح الهمزة. انظر هذه القراءة في: إتحاف الفضلاء (ص: ١٨٢)، تفسير الطبري (٧/ ٣٩٨)، التيسير (ص: ٩١)، السبعة (ص: ٢١٩)، النشر (٢/ ٢٤٤).","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
