INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 4 AND "number" = 66), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"قال الزمخشري: و «إذا» جواب سؤال مقدر، كأنه قيل: وماذا يكون لهم بعد التثبيت؟ فقيل: وإذا لو ثبتوا لآتيناهم؛ لأنَّ «إذا» جواب وجزاء، وعليه فلا يوقف على «تثبيتًا»، ولا على «عظيمًا»؛ لأنَّ قوله: «وإذا لآتيناهم»، «ولهديناهم» من جواب لو، قاله السجاوندي مع زيادة للإيضاح.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
