INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 4 AND "number" = 73), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"؛ لأنَّ قوله: «كأن لم تكن بينكم وبينه مودة» معترضة بين قوله: «ليقولن»، ومعمول القول، وهو: «يا ليتني» سواء جعلت للجملة التشبيهية محلًّا من الإعراب نصبًا على الحال من الضمير المستكن في «ليقولن»، أو نصبًا على المفعول بـ «يقولن»، فيصير مجموع جملة التشبيه، وجملة التمني من جملة المقول، أو لا محل لها؛ لكونها معترضة بين الشرط وجملة القسم وأخرت والنية بها التوسط بين الجملتين، والتقدير: ليقولن يا ليتني، انظر: أبا حيان، وتوسمه شيخ الإسلام","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
