INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 4 AND "number" = 77), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"وَآَتُوا الزَّكَاةَ، ومثله «أو أشدَّ خشية»، وكذا «القتال»؛ لأنَّ لولا بمعنى: هلَّا وهلَّا بمعنى الاستفهام، وهو يوقف على ما قبله، و «قريب»، و «قليل» كلها وقوف جائزة، وقال نافع: تام؛ لأنَّ الجملتين -وإن اتفقتا- فالفصل بين وصفي الدارين؛ لتضادهما مستحسن.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
