INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 4 AND "number" = 81), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"كاف؛ على استئناف ما بعده، وارتفع «طاعة» على أنه خبر مبتدأ محذوف، أي: أمرنا طاعةٌ لك، وقيل: ليس بوقف؛ لأنَّ الوقف عليه يوهم أنَّ المنافقين موحدون","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 4 AND "number" = 82), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"لانتهاء الاستفهام على قول من قال: المعنى ولو كان ما تخبرونه مما ترون من عند غير الله -لاختلف فيه، ومن قال: المعنى ولو كان القرآن من عند غير الله -لوجدوا فيه اختلافًا كثيرا، فعلى هذا يكون كافيا؛ لأنَّ كلام الناس يختلف فيه، ويتناقض إما في اللفظ والوصف، وإما في المعنى بتناقض الأخبار، أو الوقوع على خلاف المخبر به، أو اشتماله على ما يلتئم وما لا يلتئم، أو كونه يمكن معارضته، والقرآن ليس فيه شيء من ذلك، كذا في أبي حيان.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 4 AND "number" = 83), 0, 'BOOKS', 'APPROVED', '{"ruling":"يبنى الوقف على ذلك","explanation":"يبنى الوقف على ذلك، والوصل على اختلاف المفسرين في المستثنى منه، فقيل: مستثنى من فاعل «اتبعتم»، أي: لاتبعتم الشيطان إلَّا قليلًا منكم؛ فإنه لم يتبعه قبل إرسال محمد - صلى الله عليه وسلم -، وذلك القليل كقس بن ساعدة، وعمرو بن نفيل، وورقة بن نوفل ممن كان على دين عيسى - عليه السلام - قبل البعثة، وعلى هذا فالاستثناء منقطع؛ لأنَّ المستثنى لم يدخل تحت الخطاب، وقيل: الخطاب في قوله: «لاتبعتم» لجميع الناس على العموم، والمراد بالقليل: أمة محمد - صلى الله عليه وسلم - خاصةً، أي: هم أمة رسول الله - صلى الله عليه وسلم -، لا طائفة منهم، ويؤيد هذا القول حديث: «ما أنتم في من سواكم من الأمم إلَّا كالرقمة البيضاء في الثور الأسود» (١)، وقيل: مستثنى من قوله: «لعلمه الذين يستنبطونه منهم»، وقيل: مستثنى من الضمير في «أذاعوا به»، وقيل: مستثنى من الاتباع، كأنه قال: لاتبعتم الشيطان اتباعًا غير قليل، وقيل: مستثنى من قوله: «ولولا فضل الله عليكم ورحمته»، أي: إلَّا قليلًا منكم لم يدخله الله في فضله ورحمته، فيكون الممتنع من اتباع الشيطان ممتنعًا بفضله ورحمته، فعلى الأول يتم الكلام على «أذاعوا به»، ولا يوقف على «منهم» حتى يبلغ قليلًا؛ لأنَّ الأمر إذا ردوه إلى الرسول، وإلى أولي الأمر منهم -لعلمه الجماعة، ولم يكن للاستثناء من المستنبطين معنا، وجعله مستثنى من قوله: «ولولا فضل الله عليكم ورحمته» بعيد؛ لأنه يصير المعنى: ولولا فضل الله عليكم ورحمته لاتبع الجماعة الشيطان، والكلام في كونه استثناءً منقطعًا أو متصلًا، وعلى كل قول مما ذكر يطول شرحه، ومن أراد ذلك فعليه بـ (البحر المحيط) ففيه العذب العذاب، والعجب العجاب، وما ذكرناه هو ما يتعلق بما نحن فيه","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
