VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 4 AND "number" = 92), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"جعل أبو عبيدة، والأخفش «إلَّا» في معنى: ولا، والتقدير: ولا خطًا، والفراء جعل «إلَّا» في قوّة لكن، على معنى الانقطاع، أي: لكن من قتله خطًا فعليه تحرير رقبة، فعلى قوله يحسن الابتداء بـ «إلَّا»، ولا يوقف على خطًا؛ إذ المعنى فيما بعده.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
