INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 4 AND "number" = 148), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"إن جعلت «من» فاعلًا بالجهر، كأنه قال: لا يحب الله أن يجهر بالسوء من القول إلَّا المظلوم فلا يكره جهره به، والمصدر إذا دخلت عليه أل، أو أضيف عمل عمل الفعل، وكذلك إذا نون، نحو قوله: {أَوْ إِطْعَامٌ فِي يَوْمٍ ذِي مَسْغَبَةٍ (١٤) يَتِيمًا} [البلد: ١٤، ١٥]، وقرأ الضحاك، وزيد بن أسلم: «إلَّا من ظَلَم» بفتح الظاء واللام (١)، فعلى هذه القراءة يصح في «إلَّا» الاتصال والانقطاع، ويكون من التقديم والتأخير، وكأنَّه قال: ما يفعل الله بعذابكم إن شكرتم وآمنتم إلَّا من ظلم، فعلى هذا لا يوقف على «عليمًا» (٢).","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
