INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 4 AND "number" = 159), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"لأنَّ قوله: «ويوم القيامة» ظرف كونه شهيد إلَّا ظرف إيمانهم، قالوا: وللاستئناف، والضمير في «به»، وفي «موته» لعيسى، وقيل: إنه في «به» لعيسى، وفي «موته» للكتابي، قالوا: وليس بموت يهودي حتى يؤمن بعيسى، ويعلم أنَّه نبي، ولكن ذلك عند المعاينة والغرغرة، فهو إيمان لا ينفعه","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
