INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 4 AND "number" = 162), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"إن نصب ما بعده على المدح، أي: أمدح المقيمين، وإنما قطعت هذه الصفة عن بقية الصفات؛ لبيان فضل الصلاة على غيرها، وهو قول سيبويه، والمحققين، وليس بوقف إن عطف على «بما أنزل إليك»، أي: يؤمنون بالكتب وبالمقيمين، أو عطف على «ما من» قوله: «وما أنزل من قبلك» فإنها في موضع جر، أو عطف على الضمير في «منهم»","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
