INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 5 AND "number" = 96), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"حسن، إن نصب «متاعًا» بفعل مقدر، أي: متعكم به متاعًا، وليس بوقف إن نصب «متاعًا» مفعولًا له، أي: أحل لكم تمتيعًا لكم؛ لأنَّه يصير كله كلامًا واحدًا، فلا يقطع؛ لأنَّ متاعًا مفعول له مختص بالطعام، كما أنَّ «نافلة» في قوله: {وَوَهَبْنَا لَهُ إِسْحَاقَ وَيَعْقُوبَ نَافِلَةً} [الأنبياء: ٧٢] مختصة بـ «يعقوب»؛ لأنَّه ولد الوالد بخلاف «إسحاق»؛ فإنَّه ولده لصلبه، و «النافلة» إنما تطلق على ولد الولد دون الولد؛ فقد خصص الزمخشري كونه مفعولًا له بكون أحل مسندًا لطعامه، وليس علة لحل الصيد، وإنما هو علة لحل الطعام فقط؛ لأنَّ مذهبه أن «صيد البحر» منه ما يؤكل وما لا يؤكل، وأنَّ «طعامه» هو المأكول، وأنَّه لا يقع التمثيل إلَّا بالمأكول منه، طريًا وقديدًا، ومذهب غيره أنه مفعول له","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
