INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 5 AND "number" = 105), 0, 'BOOKS', 'APPROVED', '{"ruling":"صالح","explanation":"أي: يصلح أن يكون ما بعده مستأنفًا وحالًا، أي: احفظوا أنفسكم غير مضرورين، قرأ الجمهور: «يضرُّكم» بضم الراء مشددة، وقرأ الحسن (٢): «لا يضُرْكم» بضم الضاد وإسكان الراء، وقرأ إبراهيم النخعي (٣): «لا يضِرْكم» بكسر الضاد وسكون الراء، وقرأ أبو حيوة (٤): «لا يضْرُرُكم» بإسكان الضاد وضم الراء الأولى والثانية، و «من» فاعل، أي: لا يضركم الذي ضل وقت اهتدائكم.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
