INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 6 AND "number" = 96), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"، على قراءة: «وجعل» فعلًا ماضيًا، أي: فلق وجعل ونصب الليل والشمس والقمر، وهي قراءة الكوفيين، وأما على قراءة الباقين: «وجاعل» (٢)، فالوقف على «حسبانًا»، فعلى قراءة غير الكوفيين: الناصب للشمس والقمر فعل مقدر، تقول: هذا ضارب زيدًا الآن أو غدًا وعمرًا، فنصب عمرًا بفعل مقدر، لا على موضع المجرور باسم الفاعل، وعلى رأي الزمخشري: النصب على محل الليل، ومنه قول:","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
