INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 6 AND "number" = 100), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"{شُرَكَاءَ الْجِنَّ} [١٠٠] كاف، ومثله «وخلقهم»، وهو أكفى لمن قرأ، و «خلَقهم» بفتح اللام، وفي «الجن» الحركات الثلاث؛ فالرفع على تقدير: هم الجن، جوابًا لمن قال: من الذين جعلوا لله شركاء؟ فقيل: هم الجن، وبها قرأ أبو حيوة (٢)، والنصب على أنَّه مفعول ثان لـ «جعل»، وضعف قول من نصبه بدلًا من «شركاء»؛ لأنَّه لا يصح للبدل أن يحل محل المبدل منه، فلا يصح «وجعلوا لله الجنَّ» بالنصب قرأ العامة، و «الجنِّ» بالجر والإضافة وبها قرأ شعيب بن أبي حمزة، ويزيد بن قطيب (٣).","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 6 AND "number" = 101), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"{وَلَمْ تَكُنْ لَهُ صَاحِبَةٌ} [١٠١] حسن، ومثله «كل شيء».","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
