INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 6 AND "number" = 102), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسان","explanation":"{إِلَّا هُوَ} [١٠٢]، و {فَاعْبُدُوهُ} [١٠٢]، و {وَكِيلٌ (١٠٢)} [١٠٢] كلها حسان، ومثلها «الأبصار» الثاني.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
