INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 6 AND "number" = 143), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"لأنَّ ما بعده استئناف أمر من الله تعالى، ومثله «أم الأنثيين» إن كان حرَّم الذكور فكل ذكر حرام، وإن كان حرم الإناث فكل أنثى حرام، واحتج عليهم بهذا؛ لأنهم أحلوا ما ولد حيًّا ذكرًا للذكور، وحرموه على الإناث، وكذا إن قالوا: الأنثيان، وكانوا يحرمون أيضًا الوصيلة وأخاها على الرجال والنساء، وإن قالوا: حرم ما اشتملت عليه أرحام الأنثيين -فكل مولود منها حرام، وكلها مولود، فكلها إذًا حرام فتخصيص التحريم للبعض دون البعض تحكم -فمن أين جاء هذا التحريم؟!","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 6 AND "number" = 144), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"أيضًا، وكذا «الأنثيين»، ومثله «أرحام الأنثيين»","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 6 AND "number" = 145), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"إن جعل الاستثناء منقطعًا؛ لأنَّ المستثنى منه ذات، والمستثنى معنى، وذلك لا يجوز، وكذا لا يجوز إن جعل مفعولًا من أجله، والعامل فيه «أهل» مقدمًا عليه","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 6 AND "number" = 146), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"ظُفُرٍ، وهو للإبل والنعام، وعند أهل اللغة: أن ذا الظفر من الطير: ما كان ذا مخلب، وقوله: شحومهما، قال ابن جريج: هو كل شحم لم يكن مختلطًا بعظم، ولا على عظم، وهذا أولى؛ لعموم الآية وللحديث المسند عن رسول الله - صلى الله عليه وسلم -: «قاتل الله اليهود حرمت عليهم الشحوم فباعوها وأكلوا أثمانها»","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
