INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 6 AND "number" = 150), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"ومثله «معهم»، وكذا «بالآخرة»، على استئناف ما بعده، وقطعه عما قبله، وليس بوقف إن عطف على ما قبله","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 6 AND "number" = 151), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"ثم يبتدئ «عليكم أن لا تشركوا»، على سبيل الإغراء، أي: الزموا نفي الإشراك، وإغراء المخاطب فصيح، نقله ابن الأنباري، وأما إغراء الغائب فضعيف، والوقف على «عليكم» جائز إن جعل موضع «أن» رفعًا مستأنفًا تقديره: هو أن لا تشركوا، أو نصبًا، أي: وحرم عليكم أن لا تشركوا، و «لا» زائدة، ومعناه: حرم عليكم الإشراك، وليس بوقف إن علق «عليكم» بـ «حرم»، وهو اختبار البصريين، أو علق بـ «أتل»، وهو اختيار الكوفيين، فهو من باب الإعمال؛ فالبصريون يعملون الثاني، والكوفيون يعملون الأول، وكذا إن جعلت «أن» بدلًا من «ما»، أو جعلت «أن» بمعنى: لئلَّا تشركوا، أو بأن لا تشركوا لتعلق الثاني بالأول","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 6 AND "number" = 152), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"ومثله: «بالقسط» على استئناف ما بعده؛ للفصل بين الحكمين، وليس بوقف إن جعل ما بعده حالًا، أي: أوفوا غير مكلفين.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
