VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 7 AND "number" = 12), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"لما فيه من الفصل بين السؤال والجواب، وذلك أنَّ الفعل الذي بعده جواب إلَّا أن الفاء حذفت منه، و «ما» استفهامية مبتدأ، والجملة بعدها خبر «ما» أي: أيُّ شيء منعك من السجود، أو أن لا تسجد؟ أو ما الذي دعاك أن لا تسجد؟!","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
