VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 7 AND "number" = 24), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"وقال الأخفش: تام، إن جعل ما بعده مبتدأ خبره «لبعض عدو»، وليس بوقف إن جعل ما بعده جملة في موضع الحال من الضمير في «اهبطوا»، أي: اهبطوا متباغضين.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
