VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 7 AND "number" = 26), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"على قراءة: «ولباسُ التقوى» بالرفع خبر مبتدأ محذوف، وبها قرأ حمزة، وعاصم، وابن كثير، وأبو عمرو (١)","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
