INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 7 AND "number" = 27), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"لأنَّ «ينزع» حال من الضمير في «أخرج»، أو «من أبويكم»؛ لأنَّ الجملة فيها ضمير «الشيطان»، وضمير الأبوين ونسبة النزع والإرادة إلى الشيطان؛ لتسببه في ذلك","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 7 AND "number" = 28), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"وجه حسنه إنَّه فاصل بين الاعتقادين؛ إذ تقليد الكفار آباءهم ليس طريقًا؛ لحصول العلم، وقولهم: «والله أمرنا بها» افتراء عليه تعالى؛ إذ كل كائن مراد لله تعالى، وإن لم يكن مرضيًّا له ولا آمرًا به، وما ليس بكائن ليس بمراد له تعالى؛ إذ قد أمر العباد بما لم يشأه منهم، كأمره بالإيمان من علم موته على الكفر كإبليس، ووزيريه: أبوي جهل ولهب؛ إذ هم مكلفون بالإيمان نظرًا للحالة الراهنة؛ لقدرتهم ظاهرًا، وإن كانوا عاجزين عنه باطنًا؛ لعلم الله تعالى بأنهم لا يؤمنون؛ إذ قد علم تعالى ممن يموت على الكفر عدم إيمانه، فامتنع وجود الإيمان منه، وإذا كان وجود الإيمان ممتنعًا -فلا تتعلق الإرادة به؛ لأنَّها تخصيص أحد الشيئين بالفعل، أو الترك بالوقوع تعالى أن يكون في ملكه ما لا يريد (٥)","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 7 AND "number" = 29), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"ومثله «له الدين»، على أنَّ الكاف في محل نصب نعت لمصدر محذوف تقديره: تعودون عودًا مثل ما بدأكم، وتام إن نصب «فريقًا» بـ «هدى»، أو جعلت الجملتان مستأنفتين، وليس بوقف إن نصبتا حالين من فاعلين «تعودون»، أي: تعودون فريقًا مهديًّا، وفريقًا حاقًّا عليه الضلالة، فنصب «فريقًا» الثاني بإضمار فعل يفسره ما بعده، أي: وأضلَّ فريقًا، فهو من باب الاشتغال، وروي عن محمد بن كعب القرظي أنَّه قال في هذه الآية: يختم للمرء بما بدئ به، ألا ترى أنَّ السحرة كانوا كفارًا، ثم ختم لهم بالسعادة، وأنَّ إبليس كان مع الملائكة مؤمنًا، ثم عاد إلى ما بدئ به، فعلى هذه التأويلات لا يوقف على «تعودون»","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
