INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 7 AND "number" = 32), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"وكذا «في الحياة الدنيا»، على قراءة نافع: «خالصةٌ» بالرفع استئنافًا خبر مبتدأ محذوف تقديره: هي خالصة للمؤمنين يوم القيامة، أو الرفع خبر بعد خبر، والخبر الأول هو: للذين آمنوا، والتقدير: قل الطيبات مستقرة للذين آمنوا في الحياة الدنيا، وهي خالصة لهم يوم القيامة، وإن كانوا في الدنيا تشاركهم الكفار فيها، وليس بوقف على قراءة باقي السبعة بالنصب على الحال من الضمير المستكن في الجار والمجرور الواقع خبرًا لهي، والتقدير: قل هي مستقرة للذين آمنوا في حال خلوصها لهم يوم القيامة","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
