INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 7 AND "number" = 42), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"جائز، إن جعلت جملة «لا نكلف» خبر، «والذين آمنوا»، وليس بوقف إن جعلت جملة «أولئك» الخبر، وتكون جملة «لا تكلف» اعتراضًا بين المبتدأ والخبر، وفائدة الاعتراض تنبيه الكفار على أنَّ الجنة مع عظم محلها يوصل إليها بالعمل اليسير من غير مشقة","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
