INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 7 AND "number" = 43), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"جائز، على استئناف ما بعده، قيل: إنَّ أهل الجنة إذا سيقوا إليها وجدوا عند بابها شجرة في أصل ساقها عينان، فيشربون من واحدة منهما؛ فينزع ما في صدورهم من غل، فهو الشراب الطهور، ويشربون من الأخرى؛ فتجري عليهم نضرة النعيم، فلن يسغبوا، ولن يشحنوا بعدها أبدًا","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
