INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 7 AND "number" = 105), 0, 'BOOKS', 'APPROVED', '{"ruling":"أحسن","explanation":"على قراءة نافع (٢): «عليَّ» بتشديد ياء المتكلم؛ على أنَّ الكلام تم عند قوله: «حقيق»؛ لأنَّ «حقيق» نعت «رسول»، أي: رسول حقيق من رب العالمين أرسلت، وعلى هذا لا يوقف على «العالمين»؛ لأنَّ «حقيق» صفة «رسول»، أو خبر بعد خبر، وليس «حقيق» وقفًا إن جعلت «أن لا أقول» أن وصلتها مبتدأ، و «حقيق» خبرًا، أو «حقيق»","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
