INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 7 AND "number" = 110), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"إن جعل «فماذا تأمرون» من كلام فرعون، ويؤيد كونه من كلامه «قالوا أرجه»، و «يريد أن يخرجكم من أرضكم»؛ فهو قول الملأ، وليس بوقف إن جعل من كلام الملأ، وخاطبوا فرعون وحده بقولهم: «تأمرون» تعظيمًا له، كما تخاطب الملوك بصيغة الجمع، أو قالوا ذلك له ولأصحابه، ويجوز أن تكون «ماذا» كلها اسمًا واحدًا مفعولًا ثانيًا لـ «تأمرون»، والمفعول الأول محذوف وهو ياء المتكلم، والتقدير: بأي شيء تأمرونني؟ ويجوز أن تكون «ما» وحدها استفهامًا، «ما» مبتدأ، و «ذا» اسم موصول بمعنى: الذي خبر عنها، و «تأمرون» صلة «ذا»، ومفعول «تأمرون» محذوف،وهو ضمير المتكلم، والثاني الضمير العائد على الموصول، والتقدير: فأي شيء تأمروننيه؟ أي:تأمرونني به","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
