INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 7 AND "number" = 137), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"لأنَّ «مشارق الأرض» منصوب، على أنه مفعول ثان لـ «أورثنا»، قال السجستاني: نصبوا «مشارق» بـ «أورثنا»، ولم ينصبوها بالظرف، ولم يريدوا في مشارق الأرض وفي مغاربها، قال أبو بكر بن الأنباري: فإنكاره النصب على الظرفية خطأ؛ لأنَّ في مشارق ومغارب وجهين: أحدهما أنَّها منصوبة بـ «أورثنا» على غير معنى مخل، وهو الذي يسميه الكسائي صفة، ويسميه الخليل ظرفًا. والوجه الثاني: أن تنصب «التي» بـ «أورثنا»، وتنصب مشارق ومغارب على المحل، كأنك قلت: وأورثنا القوم الأرض التي باركنا فيها مشارق الأرض ومغاربها، فلما حذف الجار نصبا، وإذا نصبت مشارق ومغارب بوقوع الفعل عليها على غير معنى المحل -جعلت «التي باركنا فيها» نعت مشارق ومغارب، وعليهما فلا يوقف على «يستضعفون»","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
