INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 7 AND "number" = 157), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"كاف، على استئناف ما بعده، وقيل: تام؛ لأنَّ ما بعده يحتمل أن يكون خبر مبتدأ محذوف، أي: هو يأمرهم، وأن يكون نعتًا لقوله: «مكتوبًا»، أو بدلًا، أي: يجدونه آمرًا، أو صلة لـ «الذي» قائمًا مقام «يجدونه» كالبدل من تلك الجملة، أي: الأمي الذي يأمرهم، قاله السجاوندي مع زيادة للإيضاح، و «الأمي» بضم الهمزة، وهي قراءة العامة نسبة إلى الأمة، أو إلى الأم؛ فهو مصدر","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
