VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 8 AND "number" = 50), 0, 'BOOKS', 'APPROVED', '{"ruling":"بيان","explanation":"بيَّن بهذا الوقف المعنى المراد على قراءة (١): «يتوفى» بالتحتية، أنَّ الفاعل هو ضمير «يتوفى» عائد على «الله»، وأنَّ «الذين كفروا» في محل نصب مفعول «يتوفى»، و «الملائكة» مبتدأ، والخبر «يضربون»، وأن الملائكة هي الضاربة لوجوه الكفار وأدبارهم، وكذا إن جعل «الذين كفروا» فاعل «يتوفى» بالتحتية، والمفعول محذوف تقديره: يستوفون أعمالهم، و «الملائكة» مبتدأ، وما بعده الخبر، فعلى هذين التقديرين الوقف على «كفروا»، وليس بوقف لمن قرأ (٢): «تتوفى» بالفوقية أو التحتية، و «الملائكة» فاعل، و «يضربون» في موضع نصب حال من «الملائكة»، وحينئذ الوقف على «الملائكة»، ويبتدئ: «يضربون وجوههم»، فبيَّن به أنَّ الملائكة هي التي تتوفاهم، ولم يصل الملائكة بما بعده؛ لئلَّا يشكل بأنَّ الملائكة ضاربة لا متوفية، والأولى أن لا يوقف على «كفروا»، ولا على «الملائكة»، بل على قوله: «وأدبارهم»، أي: حال الإدبار والإقبال، وجواب «لو» محذوف تقديره: لرأيت أمرًا عجيبًا وشيئًا هائلًا فظيعًا (٣).","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 8 AND "number" = 51), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"والأولى وصله بـ «كدأب آل فرعون»، وتقدم ما يغني عن إعادته في آل عمران، فعليك به إن شئت، والدأب: العادة، أي: كدأب الكفار في مآلهم إلى النار، مثل مآل آل فرعون لما أيقنوا أنَّ موسى نبيٌّ فكذبوه، كذلك هؤلاء جاءهم محمد - صلى الله عليه وسلم - فكذبوه، فأنزل الله بهم عقوبة، كما أنزل بآل فرعون","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
