INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 9 AND "number" = 121), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"إِلَّا كُتِبَ لَهُمْ} [١٢١] ليس بوقف؛ لأنَّ لام «ليجزيهم الله» (لام كي)، وهي لا يبتدأ بها؛ لأنَّها متعلقة بما قبلها، وقال أبو حاتم السجستاني: تام؛ لأنَّ اللام لام قسم حذفت منه النون تخفيفًا، والأصل: (ليجزينهم) فحذفوا النون وكسروا اللام بعد أن كانت مفتوحة، فأشبهت في اللفظ (لام كي)، فنصبوا بها كما نصبوا بـ (لام كي)، قال أبو بكر بن الأنباري: وهذا غلط؛ لأنَّ لام القسم لا تكسر ولا ينصب بها، ولو جاز أن يكون معنى «ليجزيهم» (ليجزينهم) –لقلنا: والله ليقم عبد الله بتأويل، والله ليقومن. وهذا معدوم في كلام العرب، واحتج بأنَّ العرب تقول في التعجب: أكرمْ بعبد الله فيجزمونه؛ لشبهه لفظ الأمر، وقال أبو بكر بن الأنباري: وليس هذا بمنزلة ذاك؛ لأنَّ التعجب عدل إلى لفظ الأمر، ولام القسم لم توجد مكسورة قط في حال ظهور اليمين، ولا في إضماره، قال بعضهم: ولا نعلم أحدًا من أهل العربية وافق أبا حاتم في هذا القول، وأجمع أهل العلم باللسان على أنَّ ما قاله وقدره في ذلك خطأ لا يصح في لغة ولا قياس، وليست هذه لام قسم، قال أبو جعفر: ورأيت الحسن بن كيسان ينكر مثل هذا على أبي حاتم، أي: يخطئه فيه، ويعيب عليه هذا القول، ويذهب إلى أنَّها (لام كي) متعلقة بقوله: «كتب» اهـ نكزاوي، مع زيادة للإيضاح، ويقال مثل ذلك في نظائره (١).","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
