INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 9 AND "number" = 127), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"وقال الفراء: كاف؛ لأنَّ المعنى عنده: وإذا ما أنزلت سورة فيها ذكر المنافقين وعيبهم -قال بعضهم لبعض: هل يراكم من أحد إن قمتم، فإن لم يرهم أحد خرجوا من المسجد (٢)","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 9 AND "number" = 128), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"وقرئ: «من أنفَسكم» بفتح الفاء (٣)، أي: من أشرفكم، من النفاسة، وقيل: الوقف على «عزيز»؛ لأنَّه صفة «رسول»، وفيه تقديم غير الوصف الصريح، وهو من أنفسكم؛ لأنه جملة على الوصف الصريح، وهو عزيز؛ لأنَّه مفرد، ومنه: {وَهَذَا كِتَابٌ أَنْزَلْنَاهُ مُبَارَكٌ} [الأنعام: ٩٢] فـ «أنزلناه» جملة، و «مبارك» مفرد، ومنه: {يُحِبُّهُمْ وَيُحِبُّونَهُ} [المائدة: ٥٤]، وهي غير صريحة؛ لأنها جملة مؤولة بمفرد، وقوله: {أَذِلَّةٍ عَلَى الْمُؤْمِنِينَ أَعِزَّةٍ عَلَى الْكَافِرِينَ} [٥٤] صفتان صريحتان؛ لأنَّهما مفردتان كما تقدم، وقد يجاب بأنَّ «من أنفسكم» متعلق بـ «جاءكم»، وجوَّز الحوفي أن يكون «عزيز» مبتدأ، و «ما عنتم» خبره، والأرجح أنَّه صفة «رسول»؛ لقوله بعد ذلك: «حريص»، فلم يجعله خبرًا لغيره، وادعاء كونه خبر مبتدأ محذوف لا حاجة إليه؛ فقوله: «حريص عليكم» خطاب","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
