INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 10 AND "number" = 2), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"سواء أعربنا «أن أوحينا» اسم كان، و «عجبًا» الخبر، أو عكسه، والتقدير: أكان إيحاؤنا بالإنذار والتبشير إلى رجل منهم عجبًا، و «أن أنذر الناس» تفسيرًا، وجعلت «كان» تامة، و «أن أوحينا» بدلًا من «عجبًا» بدل اشتمال، أو كل من كل، وجعل هذا نفس العجب مبالغة","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
