ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 10 AND "number" = 4), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"سواء أعرب «جميعًا» حال من المضاف إليه، وهو الكاف، وهو صحيح؛ لوجود شرطه، وهو كون المضاف صالحًا للعمل في الحال، ومثله «حقًّا» لمن قرأ: «أنه يبدأ الخلق» بكسر الهمزة، وليس بوقف لمن قرأ بفتحها، وهو أبو جعفر يزيد بن القعقاع؛ فإنَّه كان يقرأ (١): «أنَّه» بفتح الهمزة، فعلى قراءته لا يوقف على «حقًّا»؛ لأنَّ ما قبلها عامل فيها، بل يوقف على «وعد الله»، ثم يبتدئ «حقًّا إنَّه يبدأ الخلق»، وقال أبو حاتم: موضع «أن» بالفتح نصب بالوعد؛ لأنَّه مصدر مضاف لمفعوله، فكأنَّه قال: وعد الله له. فعلى قوله لا يوقف على ما قبل «حقًّا»، ولا على ما بعده، وقيل: موضعه رفع، أي: حقًّا إنَّه يبدأ الخلق، كما قال الشاعر:أحقًّا عبادَ اللهِ أنْ لستُ داخلًا ... ولا خارجًا إلَّا عليَّ رقيبُ","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 10 AND "number" = 5), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"سئل أبو عمرو عن «الحساب» أتنصبه، أم تجره؟ أي: هل تعطفه على عدد فتنصبه، أو على السنين فتجره؟ فقال: لا يمكن جره؛ إذ يقتضي ذلك أن يعلم عدد الحساب، ولا يقدر أحدًا أن يعلم عدده.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
