INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 10 AND "number" = 10), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"قال سفيان: إذا أراد أحد من أهل الجنة أن يدعو بالشيء إليه قال: سبحانك اللهم. فإذا قالوها مثل بين يديه؛ فهي علامة بين أهل الجنة وخدمهم، فإذا أرادوا الطعام قالوها أتاهم حالًا ما يشتهون، فإذا فرغوا حمدوا الله تعالى، فذلك قوله: «وآخر دعواهم أن الحمد لله رب العالمين»","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 10 AND "number" = 11), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"للفصل بين الماضي والمستقبل، أي: ولو يعجل الله للناس الشر في الدعاء كاستعجالهم بالخير -لهلكوا.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 10 AND "number" = 12), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"حسن، ومثله «مسه»، وزعم بعضهم أنَّ الوقف على قوله: «فلما كشفنا عنه ضره مر» -ليس بشيء؛ لأنَّ المعنى: استمر على ما كان عليه من قبل أن يمسه الضر، ونسي ما كان فيه من الجهد والبلاء، ونسي سؤاله إيانا.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 10 AND "number" = 13), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"ليس بوقف؛ لعطف «وجاءتهم» على «ظلموا»، أي: لما حصل لهم هذان الأمران: مجيء الرسل بالبينات، وظلمهم -أهلكوا.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
