VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 10 AND "number" = 16), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"جائز، على قراءة قنبل: «ولأدراكم به» بغير نفي (1)؛ فهو استفهام وإخبار بإيقاع الراية من الله تعالى، فهو منقطع من النفي الذي قبله، وليس بوقف لمن قرأ: «ولا أدراكم»","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
