INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 10 AND "number" = 23), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"تام لمن قرأ: «متاعَ» بإضمار مبتدأ محذوف تقديره: هو متاع، أو ذلك متاع، وكذا لو نصب بمحذوف، أي: تبغون متاع، أو رفع «بغيكم» على الابتداء، و «على أنفسكم» في موضع الخبر، وفيه ضمير عائد على المبتدأ تقديره: إنما بغيكم مستقر على أنفسكم، وهو متاع، فـ «على» متعلقة بالاستقرار، وكذا لو رفع «بغيكم» على الابتداء، والخبر محذوف تقديره: إنَّما بغيكم على أنفسكم من أجل متاع الحياة مذموم، وليس بوقف إن رفع خبرًا عن قوله: «بغيكم»، و «على أنفسكم» متعلق بالبغي، فلا ضمير في قوله: «على أنفسكم»؛ لأنَّه ليس بخبر المبتدأ، فهو ظرف لغو، أو نصب «متاع» بـ «بغيكم»، أو نصب على أنه مفعول من أجله، أي: من أجل متاع، وبالنصب قرأ حفص عن عاصم؛ على أن «متاعَ» ظرف زمان، أي: زمن متاع، وقرأ باقي السبعة: «متاعُ» بالرفع","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 10 AND "number" = 24), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"لأنَّ «حتى» ابتدائية تقع بعدها الجمل، كقوله:فما زالت القتلى تمجُّ دماءَها ... بِدِجلةَ حتَّى ماءَ دجلةَ أشكلَ","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
