INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 10 AND "number" = 26), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"حسن، وقيل: كاف، وقيل: تام. قال الحسن: الحسنى: العمل الصالح. والزيادة: الجنة، وقيل: النظر إلى وجه الله الكريم، كما روي عن صهيب قال: قال رسول الله - صلى الله عليه وسلم -: «إذا دخل أهل الجنة الجنة نودوا: أن يا أهل الجنة إن لكم عند الله موعدًا أريد أن أنجزكموه، فيقولون: ما هو؟! ألم تبيِّض وجوهنا؟ ألم تزحزحنا عن النار؟ ألم تدخلنا الجنة؟ فيكشف الحجاب، فينظرون إليه، فوالله ما أعطاهم شيئًا هو أحب إليهم منه» (١)، وقيل: واحدة من الحسنات بواحدة، وزيادة تُضعَّف عشرة أمثالها إلى سبعمائة ضعف (٢)","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 10 AND "number" = 27), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"ومثله «من عاصم»؛ لأنَّ الكاف لا تتعلق بـ «عاصم»، مع تعلقه بـ «ذلة» قبلها معنى؛ لأنَّ رهق الذلة: سواد الوجه وتغيره، وكون وجوههم مسودة، وهو حقيقة، لا مجازًا، وكنَّى بالوجه عن الجملة؛ لكونه أشرفها، ولظهور السرور فيه","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 10 AND "number" = 28), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"لعطف «أنتم وشركاؤكم»؛ لأنَّ «مكانكم» اسم فعل بمعنى: اثبتوا، فأكد وعطف عليه «أنتم وشركاؤكم» و «مكانكم» اسم فعل لا يتعدى، ولهذا قدر فاثبتوا؛ لأنَّ اسم الفعل إن كان الفعل لازمًا -كان لازمًا، وإن كان متعديًا -كان متعديًا، نحو: عليك زيدًا لما ناب مناب الزم –تعدى. وقال ابن عطية: «أنتم» مبتدأ، والخبر مخزيون أو مهانون، فيكون «مكانكم» قد تم، ثم يبتدئ: «أنتم وشركاؤكم»، وهذا لا ينبغي أن يقال؛ لأنَّ فيه تفكيكًا لأفصح كلام، ومما يدل على ضعفه قراءة من قرأ (٢): «وشركاءَكم» بالنصب على المعية، والناصب له اسم الفعل","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
