INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 10 AND "number" = 51), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"{آَمَنْتُمْ بِهِ} [٥١] حسن، التقدير: قل لهم يا محمد عند نزول العذاب: تؤمنون به –قالوا: نعم، قال: يقال لكم الآن: تؤمنون وقد كنتم بالعذاب تستعجلون استهزاءً به، وليس شيء من العذاب يستعجله عاقل؛ إذ العذاب كله مر المذاق.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
