INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 10 AND "number" = 81), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"لمن قرأ (١): «آلسحر» بالمد على الاستفهام خبر مبتدأ محذوف، أي: هو السحر، أو مبتدأ والخبر محذوف، أي: السحر هو، وليس بوقف لمن قرأ (٢): «السحر» على الخبر، لا على الاستفهام على البدل من «ما» في قوله: «ما جئتم به»؛ لاتصاله بما قبله، وبالمد قرأ أبو عمرو بن العلاء على جهة الإنكار عليهم؛ لأنَّ موسى عليه السلام لم يرد أن يخبر السحرة أنَّهم أتوا بسحر؛ لأنَّهم يعلمون أنَّ الذي أتوا به سحر، ولكنه أراد الإنكار عليهم، فلو أراد إخبارهم بالسحر لما قالوا له: أنت ساحر، وقد جئت بالسحر -لقال لهم: ما جئتم به هو السحر على الحقيقة، وليس بوقف لمن قرأه بهمزة وصل؛ لأنَّ «ما» بمعنى: الذي مبتدأ خبره «السحر»، والوقف عنده «السحر»، وفي الوجه الأول: «سيبطله» (٣).","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
