VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 10 AND "number" = 96), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"لَا يُؤْمِنُونَ (٩٦)؛ لأنَّ «لو» تعلقها بما قبلها، أي: لو جاءتهم كل آية لا يؤمنون","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
