INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 10 AND "number" = 97), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"الْأَلِيمَ (٩٧) عند يعقوب، وليس بجيد؛ لأنَّ الكلام متصل بعضه ببعض، وكذا عنده فنفعها إيمانها، وجعل يعقوب الاستثناء منقطعًا من غير الجنس، والتقدير: لكن قوم يونس، فقوم يونس لم يندرجوا في قوله: «قرية»، وإلى الانقطاع ذهب سيبويه، والفراء، والأخفش، وقيل: متصل، كأنه قيل: ما آمنت قرية من القرى الهالكة إلَّا قوم يونس؛ وهم أهل نينوى من بلاد الموصل كانوا يعبدون الأصنام، فبعث الله إليهم سيدنا يونس - عليه السلام -، فأقاموا على تكذيبه سبع سنين، وتوعدهم بالعذاب بعد ثلاثة أيام، فلم يرجعوا حتى دنا الموعد، فغامت السماء غيمًا أسود ذا دخان شديد، فهبط حتى غشي مدينتهم، فهابوا فطلبوا يونس فلم يجدوه، فأيقنوا صدقه؛ فلبسوا المسوح، وبرزوا إلى الصعيد بأنفسهم ونسائهم وصبيانهم ودوابهم، وفرقوا بين كل والدة وولدها، فحنَّ بعضها إلى بعض، وعلت الأصوات والضجيج، وأخلصوا التوبة، وأظهروا الإيمان، وتضرعوا إلى الله تعالى فرحمهم وكشف عنهم، وكان يوم عاشوراء يوم الجمعة","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
