VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 10 AND "number" = 100), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"إِلَّا بِإِذْنِ اللَّهِ، وقال أبو عمرو: كاف، لمن قرأ: «ونجعل الرجس» بالنون، وحسن لمن قرأه بالتحتية؛ لتعلقه بما قبله","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 10 AND "number" = 101), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"يجوز في «ماذا» أن تكون كلمة واحدة استفهامًا مبتدأ، «وفي السموات» خبره، ويجوز أن تكون «ما» وحدها مبتدأ، و «ذا» كلمة وحدها، وذا: اسم موصول بمعنى: الذي، «وفي السموات» صلتها، وهو خبر المبتدأ، وعلى التقدير فالمبتدأ والخبر في محل نصب بإسقاط الخافض.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 10 AND "number" = 103), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"على أنَّ الكاف في محل رفع، أي: الأمر كذلك يحق علينا ننج المؤمنين، وعلى أنها في محل نصب نعتًا لمصدر محذوف، أي: إنجاء مثل ذلك يحق علينا ننج المؤمنين، فيوقف على «كذلك»، ثم يبتدأ به؛ لتعلقه بما بعده من جهة المعنى فقط، وعلى أنَّها متعلقة بما قبلها، كأنَّه قال: ننجي رسلنا والذين آمنوا كذلك، فالتشبيه من تمام الكلام. والوقف على «كذلك»، ولا يبتدأ بها؛ لعدم تعلق ما بعدها بما قبلها، ورسموا «ننج المؤمنين» بحذف الياء بعد الجيم كما نرى.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
