VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 11 AND "number" = 9), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"{كَفُورٌ (٩)} [٩] كاف، ومثله: «السيئات عني»، و «فخور» على أنَّ الاستثناء منقطع بمعنى: لكن الذين صبروا، فـ «الذين» مبتدأ، والخبر «أولئك لهم مغفرة»، وهو قول الأخفش، وقال الفراء: هو متصل، وعليه فلا يوقف على «فخور»، بل على «الصالحات»، وعلى قول الأخفش لا يوقف على «الصالحات»؛ لفصله بين المبتدأ وخبره.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
