INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 11 AND "number" = 17), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"وقيل: تام، أي: ويتلو القرآن شاهد من الله تعالى، وهو جبريل، وهذا على قراءة العامة برفع «كتابُ»، ومن نصبه وبها قرأ محمد بن السائب الكلبي عطفًا على الهاء في «يتلوه» (١)، أي: ويتلو القرآن، وكتاب موسى شاهد من الله وهو جبريل، فوقفه «ورحمة»، وعن عليٍّ كرم الله وجهه قال: (ما من رجل من قريش إلَّا وقد نزلت فيه الآية والآيتان، فقال رجل من قريش: فأنت أي شيء نزل فيك؟ فقال: «ويتلوه شاهد منه». (٢)، وقيل: الشاهد لسانه - صلى الله عليه وسلم -، وفي الشاهد أقوال كثيرة؛ كلها توجب الوقف على «منه».","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
