VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 11 AND "number" = 46), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"على قراءة من قرأ: «إنَّه عمل غير صالح» برفع «عمَلٌ» وتنوينه وفتح الميم، وبها قرأ ابن كثير، ونافع، وعاصم، وأبو عمرو، وحمزة، وابن عامر (١)؛ وذلك على أنَّ الضمير في «إنَّه» الثاني يعود إلى السؤال، كأنَّه قال: سؤالك يا نوح إياي أن أنجيه كافرًا ما ليس لك به","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
