INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 11 AND "number" = 71), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"على أن لا تقديم في الكلام ولا تأخير، ويكون المعنى: أنهم لمَّا لم يأكلوا من طعام إبراهيم - صلى الله عليه وسلم - خافهم، فلما تبينوا ذلك في وجهه –قالوا: لا تخف، فضحكت امرأته سرورًا بالبشارة بزوال الخوف، وهذا قول السدي. والرسل هنا: جبريل، وميكائيل، وإسرافيل ذكره جماعة من المفسرين، وقال قتادة: ضحكت من غفلة القوم، وقد جاءهم العذاب. وقال وهب: ضحكت تعجبًا من أن يكون لها ولد وقد هرمت، وقيل: ضحكت حين أخبرتهم الملائكة أنَّهم رسل، وقيل: كانت قالت لإبراهيم سينزل بهؤلاء القوم عذاب، فلما جاءت الرسل سرت بذلك، وقيل: ضحكت من إبراهيم؛ إذ خاف من ثلاثة وهو يقوم بمائة رجل. وقال مجاهد: ضحكت بمعنى: حاضت. قال الفراء: لم أسمعه من ثقة، ووجهه أنَّه كناية. وقال الجمهور: هو الضحك المعروف. وقيل: هو مجاز معبر به عن طلاقة الوجه وسروره بنجاة أخيها لوط وهلاك قومه","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
