INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 12 AND "number" = 15), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"يبنى الوقف على «الجب» على اختلاف التقادير؛ فإن جعل جواب «لما» محذوفًا تقديره: فعلوا به ما أجمعوا عليه من الأذى، أو سروا بذهابهم به وإجماعهم على ما يريدون. والواو في «وأوحينا» عاطفة على ذلك المقدر، ولم يجعل «وأوحينا» جواب «لما»؛ لعدم صحته؛ وذلك أنَّ الإيحاء كان بعد إلقائه في الجبِّ، فليس مرتبًا على عزمهم على ما يريدون، وإنَّما يترتب الجواب المقدر، وبهذا يحسن الوقف على «الجب»، ويحسن أيضًا على استئناف «وأوحينا»، ولم يجعل داخلًا تحت جواب «لما»","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
