INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 12 AND "number" = 92), 0, 'BOOKS', 'APPROVED', '{"ruling":"بيان","explanation":"بيَّن به أن قوله: «اليوم» ليس ظرفًا لقوله: «لا تثريب»، وإنَّما هو متعلق بمحذوف، أي: ادعوا، ثم استأنف «اليوم يغفر الله لكم» بشرهم بالمغفرة؛ لما اعترفوا بذنبهم، وتابوا فتيب عليهم، وقيل: متعلق بقوله: «لا تثريب». والوقف على «اليوم»، قاله نافع، ويعقوب، ثم ابتدأ «يوسف»، فقال: «يغفر الله لكم»، فدعا لهم بالمغفرة لما فرط منهم، قال أبو حيان ردًّا على الزمخشري: قوله: إن «اليوم» متعلق بقوله: «لا تثريب عليكم». أما كون «اليوم» متعلقًا بـ «تثريب»، فهذا لا يجوز؛ لأنَّ التثريب مصدر، وقد فصل بينه وبين معمول بقوله: «عليكم». و «عليكم» إما أن يكون خبرًا، أو صفة لـ «تثريب»، ولا يجوز الفصل بينهما؛ لأنَّ معمول المصدر من تمامه، وأيضًا لو كان «اليوم» متعلقًا بـ «تثريب» لم يجز بناؤه، وكان يكون من قبيل الشبيه بالمضاف معربًا منونًا، وبناؤه هنا على قلة، انظر المعنى، ومعنى «لا تثريب»: لا تعيير، ولا بأس، ولا لوم، ولأذكركم ذنبكم بعد اليوم. وأصل","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
