INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 12 AND "number" = 105), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"جائز، على قراءة عكرمة (١): «والأرضُ» بالرفع مبتدأ، والخبر جملة «يمرون عليها»، وكذا من قرأ بالنصب (٢)؛ على الاشتغال، أي: يطؤن الأرض، ويروى عن ابن جريج: أنه كان ينصب «الأرض» بفعل مقدر، أي: يجوزون الأرض، وهذه القراءة ضعيفة في المعنى؛ لأنَّ الآيات في السموات وفي الأرض، والضمير في «عليها» للآية، فتكون «يمرون» حالًا منها. وقال أبو البقاء: حالًا منها، «ومن السموات»، فيكون الحال من شيئين، وهذا لا يجوز؛ لأنهم لا يمرون في السموات إلَّا أن يراد: يمرون على آياتها، فعلى هذه القراءة الوقف على «السموات» أيضًا، وكذا من نصبها بـ «يمرون»، وليس بوقف لمن جرها عطفًا على ما قبلها.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 12 AND "number" = 108), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"حسن، تقدم أنه - صلى الله عليه وسلم - كان يتعمد الوقف على ذلك، ثم يبتدئ «على بصيرة أنا ومن اتبعني» إن اجعل «أنا» مبتدأ، و «على بصيرة» خبرًا. وليس بوقف إن جعل «على بصيرة» متعلقًا","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
