INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 13 AND "number" = 2), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"تَرَوْنَهَا (٢) حسن، على أنَّ «بغير عمد» متعلق بـ «رفع»، أي: رفع السموات بغير عمد ترونها؛ فالضمير من «ترونها» يعود على «عمد»، كأنَّه قال: للسموات عمد، ولكن لا ترى، وقال ابن عباس: إنَّها بعمد، ولكن لا ترونها، قال: وعمدها جبل ق المحيط بالدنيا، وهو من زبرجد أخضر من زبرجد الجنة، والسماء مقبية فوقه كالقبة، وخضرتها من خضرته، فيكون «ترونها» في موضع الصفة لـ «عمد»، والتقدير: بغير عمد مرئية، وحينئذ فالوقف على «السموات» كاف، ثم يبتدئ: «بغير عمد ترونها»، أي: ترونها بلا عمد. وقال الكواشي: الضمير في «ترونها» يعود إلى «السموات»، أي: ترون السموات قائمة بغير عمد، وهذا أبلغ في الدلالة على القدرة الباهرة، وإذًا الوقف على «عمد»؛ ليبين أحد التأويلين من الآخر، ثم يبتدئ: «ترونها»، أي: ترونها كذلك. فـ «ترونها» مستأنف، فيتعين أن لا عمد لها ألبتة؛ لأنَّها سالبة تفيد نفي الموضوع. وإن قلنا: إنَّ «ترونها» صفة تعين أنَّ لها عمدًا، وحاصله أنهما شيئان: أحدهما","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
