INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 13 AND "number" = 10), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"للفصل بين المتقابلات، ومثله يقال في «مستخف بالليل وسارب بالنهار» حسنه أبو حاتم، وأبو بكر، والظاهر أنَّهما إنما حسناه؛ لاستغناء كل جملة عما بعدها لفظًا، أو ليفرقا بين علم الله وعلم غيره، وأباه غيرهما، وقال: كله كلام واحد، فلا يفصل بينهما، وانظر ما وجهه.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
