INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 16 AND "number" = 41), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"وقال يحيى بن سلام: الحسنة هي المدينة المشرَّفة، «ولأجر الآخرة أكبر» يعني: الجنة، نزلت في صهيب، وبلال، وخباب، وعمار بن ياسر عذبهم المشركون بمكة، وأخرجوهم من ديارهم، ولحق منهم طائفة الحبشة، ثم بوَّأهم الله دار الهجرة، وجعلهم أنصارًا «لنبوِّئنهم في الدنيا حسنة» أنزلهم المدينة، وأطعمهم الغنيمة؛ فهذا هو الثواب في الدنيا (٤)","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
