INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 16 AND "number" = 43), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"ومثله: «لا تعلمون»، إن جعل «بالبينات والزبر» متعلقًا بمحذوف صفة لـ «رجالًا»؛ لأنَّ «إلَّا» لا يستثنى بها شيئان دون عطف، أو بدلية. وما ظن غير ذلك معمولًا لما قبل «إلَّا» قدر له عامل، أو أنه متعلق بمحذوف جوابًا لسؤال مقدر يدل عليه ما قبله، كأنَّه قيل: بم أرسلوا؟ فقيل: أرسلوا بالبينات والزبر؛ فـ «البينات» متعلق بـ «أرسلنا» داخلًا تحت حكم الاستثناء مع «رجالًا»، أي: وما أرسلنا إلَّا رجالًا بالبينات؛ فقد استثني بـ «إلَّا» شيئان: أحدهما «رجالًا»، والآخر «بالبينات». وليس بوقف إن علق بـ «نوحي»؛ لأنَّ ما بعد «إلَّا» لا يتعلق بما قبلها، وكذا إن علق بقوله: «لا تعلمون» على أن الشرط في معنى: التبكيت والإلزام، كقول الأجير: إن كنت عملت لك فأعطني حقي","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
