INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 16 AND "number" = 66), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"لمن قرأ (١): «نسقيكم» بالنون استئنافًا؛ لأنَّه لا يجوز أن تكون الجملة خبر مبتدأ محذوف، أي: هي، أي: العبرة نسقيكم.ويجوز أن تكون مفسرة للعبرة، كأنَّه قيل: كيف العبرة؟ فقيل: نسقيكم من بين فرث ودم لبنًا خالصًا؛ لأنَّه إذا استقر علف الدابة في كرشها طبخته -فكان أسفله فرثًا، وأوسطه لبنًا، وأعلاه دمًا، سبحانه من عظيم! ما أعظم قدرته!","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
