INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 16 AND "number" = 69), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"يخرج من أفواه النحل؛ وذلك أنَّ العسل ينزل من السماء، فينبت في أماكن، فيأتي النحل فيشربه، ثم يأتي الخلايا التي تصنع له، والكوى التي تكون في الحيطان، فيلقيه في الشمع المهيأ للعسل في الخلايا كما يتوهمه بعض الناس؛ أنَّ العسل من فضلات الغذاء، وأنَّه قد استحال في المعدة عسلًا. ونزل من السماء عشرة أشياء مع العسل، قاله الكواشي.قال ابن حجر: فعلى أنَّه يخرج من فم النحل فهو مستثنى من القيء، وعلى أنَّه من دبرها فهو مستثنى من الروث، وقيل: من ثقبتين تحت جناحها فلا استثناء إلَّا بالنظر إلى أنَّه كاللين، وهو من غير المأكول نجس. اهـ، قال السمين: نقلوا في العسل التذكير والتأنيث، وجاء القرآن على التذكير في قوله: «من عسل مصفى»، وكنى بالعسيلة عن الجماع؛ لمشابهتهما.قال عليه الصلاة والسلام: «لا حتى تذوقي عسيلته ويذوق عسيلتك» (١)","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
