INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 16 AND "number" = 103), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"تام، وجملة «لسان الذي» مستأنفة. وقيل: حال من فاعل «يقولون»، أي: يقولون ذلك والحالة هذه، أي: علمهم بأعجمية هذا البشر، وآياته عربية هذا القرآن -كانت تمنعهم من تلك المقالة، قاله أبو حيان. قال ابن عباس: كان في مكة غلام أعجمي لبعض قريش يقال له: بلعام، فكان رسول الله - صلى الله عليه وسلم - يعلمه الإسلام، ويوقفه عليه، فقال المشركون: إنَّما يعلمه بلعام النصراني، فنزلت على النبي - صلى الله عليه وسلم - هذه الآية. وقيل: غير ذلك (١)","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
