INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 17 AND "number" = 71), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"أي: بنبيهم. وقيل: بكتابهم الذي أنزل عليهم. وقيل: كل يدعي بإمام زمانهم، وكتاب ربهم، وسنة نبيهم. وقيل: بأعمالهم. قال السمين: قال الزمخشري: ومن بدع التفاسير أنَّ الإمام جمع (أم)، وأنَّ الناس يدعون يوم القيامة بأمهاتهم دون آبائهم، وأن الحكمة فيه رعاية حق عيسى ابن مريم، وإظهار شرف الحسن والحسين، ولئلَّا تفتضح أولاد الزنا","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
