VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 17 AND "number" = 78), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"إن نصب ما بعده على الإغراء، أي: الزموا قرآن الفجر، أو وعليك قرآن الفجر، كذا قدره الأخفش، وتبعه أبو البقاء، والأصول تأبى هذا؛ لأنَّ أسماء الأفعال لا تعمل مضمرة، والأجود الوقف على «وقرآن الفجر»؛ لأنَّه معطوف على الصلاة، أي: أقم الصلاة. و «قرآن الفجر»، أي: صلاة الفجر","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
