INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 17 AND "number" = 88), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"لَا يَأْتُونَ بِمِثْلِهِ؛ لأنَّ ما قبله قد قام مقام جواب «لو»، فكأنه قال: لو كان بعضهم لبعض ظهيرًا لا يأتون بمثله. و «لا يأتون» جواب القسم المحذوف، وقيل: جواب الشرط، واعتذروا عن رفعه بأن الشرط ماضٍ؛ فهو كقوله:وَإِن أَتاهُ خَليلٌ يَومَ مسغبةٍ ... يَقولُ لا غائِبٌ مالي وَلا حَرِمُ فأجاب الشرط مع تقدم اللام الموطئة في «لئن» الداخلة على الشرط، وهو دليل للفراء ومن تبعه، وعلى كلا التقديرين ليس بوقف؛ لفصله بين الشرط وجوابه.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
