INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 18 AND "number" = 12), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"و «أي الحزبين» مبتدأ ومضاف إليه، و «أحصى» أفعل تفضيل خبر و «أمدًا» تمييز؛ لأنَّ الأمد هو: الغاية، وهو عبارة عن: المدة، وليس هو: محصيًا، بل يحصى، ومثل أعماله في التمييز أيضًا: «أنا أكثر منك مالًا وأعز نفرًا»، «هم أحسن أثاثًا ورئيًا»، وقيل: «أحصى» فعل ماض، و «أمدًا» مفعول (١).","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
