VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 18 AND "number" = 15), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"للابتداء بـ «لولا»، وهي هنا للتحضيض؛ بمعنى: هلاَّ يأتون على عبادتهم الأصنام بحجة واضحة، ولا يجوز أن تكون هذه الجملة التحضيضية صفةً لآلهة لفساده معنى وصناعة؛ لأنَّها جملة طلبية.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 18 AND "number" = 16), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"على استئناف ما بعده، وليس بوقف إن علق ما بعده بما قبله؛ لأنَّ قوله: «فأووا» عند الفراء جواب: «إذ»؛ لأنّها قد تكون للمستقبل كـ «إذا»، ومثل هذا في الكلام: إذا فعلت كذا فانج بنفسك، فلا يحسن الفصل في هذا الكلام دون الفاء؛ لأنَّ هنا جملًا محذوفة دل عليها ما تقدم مرتبطة بعضها ببعض، والتقدير: فأووا إلى الكهف، فألقى الله عليهم النوم، واستجاب دعاءهم، وأرفقهم في الكهف بأشياء.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
