INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 18 AND "number" = 90), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"وقد اختلف في الكاف من «كذلك» فقيل: في محل نصب، وقيل: في محل رفع، فإن كانت في محل رفع، أي: الأمر كذلك، أي: بلغ مطلع الشمس، كما بلغ مغربها، أو كما وجد عند مغربها قومًا وحكم فيهم، وجد عند مطلعها قومًا وحكم فيهم، أو كما أتبع سببًا إلى مغرب الشمس، كذلك أتبع سببًا إلى مطلعها، وكذلك إن كانت الكاف في محل نصب، أي: فعلنا مثل ذلك فعلى هذه التقديرات التشبيه من تمام الكلام وصار ما بعد الكاف وما قبلها كالكلام الواحد، فيبتدئ: «وقد أحطنا»، وإن لم تكن الكاف لا في محل رفع ولا في محل نصب كان التشبيه مستأنفًا منقطع لفظًا متصل معنى، فيبتديء: «كذلك»، أي: علمناهم، ليس لهم ما يستترون به، فالسِتر بكسر السين: اسم لما","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
