INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 19 AND "number" = 34), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"لمن قرأ: «قول الحق» بالنصب، وهو عاصم وحمزة وابن عامر (٣)؛ على أنَّ قول مصدر مؤكد لمضمون الجملة، أي: هذا الإخبار عن عيسى ابن مريم ثابت صدق، فهو من إضافة الموصوف إلى الصفة، كقولهم: وعد الصدق، أي: الوعد الصدق، وكذا كافٍ؛ إن رفع «قول» على قراءة من قرأه برفع اللام (٤)؛ على أنَّه خبر مبتدأ محذوف، أي: ذلك قول الحق، أو ذلك الكلام قول الحق، أو هو قول الحق، يراد به: عيسى ابن مريم لا ما تدعونه عليه، فليس هو بابن الله تعالى كما تزعم النصارى، ولا لغير رشدة كما تزعم اليهود، وليس بوقف إن رفع «قول» بدلًا من «عيسى»؛ لأنَّه لا يفصل بين البدل والمبدل منه بالوقف (٥)","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
