VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 21 AND "number" = 31), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"ليس بوقف؛ لأنَّ قوله: «أن تميد» موضعه نصب بالـ (جعل)، وقال المبرد: وهو على حذف مضاف، تقديره: كراهة أن تميد بهم، فحذف (كراهة)، وأقيم ما بعدها مقامها، وقال آخرون: أراد لئلا تميد بهم، وكذلك: «سبلًا» ليس بوقف؛ وذلك أنَّ قوله: «يهتدون» في معنى: ليهتدوا، وهذا إذا جعلت (لعل) من صلة (جعل) الأول، وإن جعلت من صلة (جعل) الثاني، كان الوقف على «بهم» حسنًا.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
