INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 21 AND "number" = 51), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"إن جعل «إذ قال لأبيه» منصوبًا بـ «عالمين»، وليس بوقف إن جعل «إذ» منصوبًا «بآياتنا»، أو بـ «رشده»، والتقدير: ولقد آتينا إبراهيم رشده في الوقت الذي قال فيه لأبيه وقومه ما ذكر، وهو بعيد من المعنى بهذا التقدير، وحينئذ لا يوقف على «عالمين» في الوجهين؛ لأنَّ «إذ» إن كانت متصلة بالفعل الأول، فلا يجوز الوقف على ما بعد الناصب دون المنصوب، وكذا إن كانت متصلة بالثاني. انظر: السمين","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
