INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 21 AND "number" = 59), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"على جعل «مَن» استفهامية، والجملة من قوله: «إنَّه لمن الظالمين» مستأنفة، وليس بوقف إن جعلت «مَن» موصولة؛ بمعنى: الذي، والجملة (من أنَّه ... ) الخ في محل رفع خبر الموصول، والتقدير: الذي فعل هذا بآلهتنا إنَّه لمن الظالمين","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
