INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 21 AND "number" = 72), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"عند نافع إن نصب «نافلةً» حالًا من «يعقوب» فقط؛ لأنَّ النافلة مختصة به؛ لأنَّها ولد الولد بخلاف إسحاق؛ فإنَّه ولد لصلبه، والتقدير: ووهبنا له يعقوب حالة كونه نافلة، ويكون من عطف الجمل، وليس بوقف إن نصب «نافلةً» انتصاب المصدر من معنى العامل، وهو: «وهبنا» لا من لفظه، فهي كالعاقبة، والعافية فيكون شاملًا لإسحاق ويعقوب؛ لأنَّهما زيدا لإبراهيم بعد ابنه إسمعيل، فلا يفصل بينهما، وكذا لا يصح الوقف على إسحاق إن عطف «يعقوب» على «إسحاق» عطف مفرد على مفرد من غير إضمار فعل؛ لتعلق ما بعده بما قبله من جهة المعنى؛ لأنَّه معطوف على ما قبله","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
