INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 21 AND "number" = 96), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"على استئناف ما بعده، وليس بوقف إن جعل جواب «إذا»، اقترب الوعد، والواو زائدة، وإن جعل جوابها: «يا ويلنا» لا وقف من قوله: «حتى إذا فتحت» إلى «ظالمين»، وهو: كاف، ومن وقف «فإذا هي واقعة»؛ يعني: يوم القيامة، ثم يبتدئ: «شاخصة أبصار الذين كفروا»؛ على أنَّ الفاء في جواب «إذا» السابقة، و «إذا» الثانية الفجائية، و «هي» ضمير القصة مبتدأ، و «هي» زائدة، و «أبصار» مبتدأ ثان، و «شاخصة» خبره، والجملة خبر عن ضمير القصة","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
