INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 21 AND "number" = 104), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"والسجل: الصحيفة، وقيل: السجل كاتب كان لرسول الله - صلى الله عليه وسلم -، والأوّل أولى لتعدد كتّابه - صلى الله عليه وسلم -، فالكاتب لا يعرف، ولا يحمل كتاب الله على ما لا يعرف، وقيل السجل: اسم ملك يطوي السماء كطي الملك لكتاب الصحيفة التي يكتب فيها أعمال العباد، فهو مصدر مضاف لفاعله، وقرأ الأخوان (٢) وحفص: «للكتب» جمعًا، والباقون: «للكتاب» بالأفراد (٣)","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
