INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 22 AND "number" = 6), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"جائز؛ لأنَّ «لوما» بمعنى: لولا، والاستفهام له الصدارة، وجواب «لوما» في سورة ن: {مَا أَنْتَ بِنِعْمَةِ رَبِّكَ بِمَجْنُونٍ (٢)} [القلم: ٢]، ولا مانع من تعلق آية بآية ليست من السورة، وإنَّما صح ذلك؛ لأنَّ القرآن كله كسورة واحدة، كما صرَّحوا من أنَّ {لِإِيلَافِ قُرَيْشٍ (١)} [قريش: ١] متعلق بقوله: {فَجَعَلَهُمْ كَعَصْفٍ مَأْكُولٍ (٥)} [الفيل: ٥]","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
