INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 22 AND "number" = 89), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"إن علقت الكاف بمصدر محذوف تقديره: آتيناك سبعًا من المثاني إيتاءً كما أنزلنا، أو إنزالًا كما أنزلنا، أو أنزلنا عليهم العذاب كما أنزلنا؛ لأنَّ «آتيناك» بمعنى: أنزلنا عليك، أو علقت بمصدر محذوف، العامل فيه مقدر تقديره: متعناهم تمتيعًا كما أنزلنا، وليس بوقف إن نصب بالنذير، أي: النذير عذابًا كما أنزلنا على المقتسمين، وهم: قوم صالح؛ لأنَّهم قالوا: «لنبيتنه وأهله»، فأقسموا على ذلك","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 22 AND "number" = 90), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"؛ لأنَّ «الذين» من نعتهم، أو بدل. «المقتسمين» هم: عظماء كفار قريش؛ أقسموا على طريق مكة يصدون عن النبي - صلى الله عليه وسلم -، فمنهم من يقول: الذي جاء به محمد سحر، ومنهم من يقول: أساطير الأولين، ومنهم من يقول: هو كهانة. فأنزل الله بهم خزيًا، وأنزل: {وَقُلْ إِنِّي أَنَا النَّذِيرُ الْمُبِينُ (٨٩) كَمَا أَنْزَلْنَا عَلَى الْمُقْتَسِمِينَ (٩٠)} [٨٩، ٩٠]، أو هم اليهود؛ فقد جرى على بني قريظة، وبني النضير ما جرى، وجعل المتوقع بمنزلة الواقع، وهو من الإعجاز؛ لأنَّه إخبار بما سيكون، وقد كان","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
