INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 24 AND "number" = 54), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"حسن، وليس بكاف؛ لأن الذي بعده داخل في الخطاب، وربما غلط في هذا الضعيف في العربية فيتوهم أن «فإنّ تولوا» الغائب، وأنه منقطع مما قبله في اللفظ وفي المعنى، وليس الأمر كذلك، وعدوا له من الخطاب إلى الغيبة موجب للوقف، بل هو على حذف إحدى التاءين، والتقدير: فإن تتولوا فهو خطاب، والدليل على ذلك: أنَّ ما بعده «وعليكم ما حملتم»، ولو كان لغائب لكان: وعليهم ما حملوا، فدل هذا على أنّ الخطاب كله متصل وبعده أيضًا «وإن تطيعوه تهتدوا».","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 24 AND "number" = 55), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"حسن؛ على استئناف ما بعده؛ كأنّ قائلًا قال: ما بالهم يستخلفون ويؤمنون؟ فقال: يعبدونني، وليس بوقف إن جعل حالًا من «وعد الله»، أي: وعدهم الله، ذلك في حال عبادتهم وإخلاصهم، ولا محل ليعبدونني من الإعراب على التقدير الأول، وعلى الثاني محله نصب.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
