INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 25 AND "number" = 7), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"{(مَالِهَذَا الرَّسُولِ يَأْكُلُ الطَّعَامَ وَيَمْشِي فِي الْأَسْوَاقِ} [٧] حسن، واتفق علماء الرسم على قطع «مال» عن «هذا»، وكذا: {فَمَالِ هَؤُلَاءِ الْقَوْمِ} [٧٨] في النساء، و {مَالِ هَذَا الْكِتَابِ} [٤٩] في الكهف، و {فَمَالِ الَّذِينَ كَفَرُوا} [٣٦] في المعارج، كتبوا هذه الأربعة منفصلة عما بعدها كلمتين؛ ووجه انفصال هذه الأربعة ما حكاه الكسائي: من أنَّ ما جرى مجرى ما بال، وما شأن، وإنّ قوله: مال زيد، وما بال زيد؛ بمعنى: واحد، وقد صح أنَّ اللام في الأربعة لام جر، والأصل: أنَّ الرسم سنة متبعة لا يعلل، وقيل: لا يحسن الوقف على «الأسواق»؛ لأنَّ ما بعده من تمام الحكاية إلى «يأكل منها» فلا يوقف على «الأسواق»، ولا على «نذيرًا» للعطف بـ «أو».","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
