INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 25 AND "number" = 17), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"{مِنْ دُونِ اللَّهِ} [١٧] كاف، لمن قرأ: «نحشرهم» بالنون والياء التحتية، في: «فيقول» لعدوله من التكلم إلى الغيبة، وليس بوقف لمن قرأهما: بالنون، وهو ابن عامر، وكذا من قرأهما: بالياء، وهو ابن_________(١) وجه من قرأ برفع اللام؛ أن ذلك على الاستئناف، أي: وهو يجعل. ووجه من قرأ: بجزمها عطفًا على محل «جعل»؛ لأنه جواب الشرط، ويلزم منه وجوب الإدغام لاجتماع مثلين أولاهما ساكن. انظر هذه القراءة في: إتحاف الفضلاء (ص: ٣٢٧)، الإعراب للنحاس (٢/ ٣٥٩)، الكشاف (٣/ ٨٣)، النشر (٢/ ٣٣٣).","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
