INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 25 AND "number" = 19), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"لمن قرأ: «يستطيعون» بالياء التحتية للعدول من الخطاب إلى الغيبية، وليس بوقف لمن قرأه: بتاء الخطاب، والمراد: عبادها، وبها قرأ: حفص، والباقون: بياء الغيبية (٣)، والمراد: الآلهة التي كانوا يعبدونها من عاقل وغيره، ولذلك غلب العاقل فجيء بواو الضمير","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
