INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 25 AND "number" = 20), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"لأنَّ «إلّا أنَّهم ليأكلون الطعام» تحقيق بعد نفي، وكسروا (إن) بعد إلّا؛ لأنَّ في خبرها اللام، وقيل: كسرت؛ لأنَّ الجملة بعد «إلّا» في موضع الحال، قال ابن الأنباري، والتقدير: ألا وإنَّهم؛ يعني: أنَّها حالية تقدر معها الواو بيانًا للحالية، والعامة على كسر همزة (إن)، وقرأ سعيد بن جبير (٥): بفتحها؛ على زيادة اللام","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
