INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 25 AND "number" = 32), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"جُمْلَةً وَاحِدَةً كَذَلِكَ} [٣٢] كاف؛ إن جعل التشبيه من تمام الكلام، أي: هلا نزل القرآن على محمد - صلى الله عليه وسلم - جملة واحدة، كما أنزلت التوراة على موسى كغيرها من الكتب، قال تعالى: «لنثبت به فؤادك»، أي: «أنزلناه مفرّقًا لنثبت به فؤادك»، أي: لنقوي به قلبك، وقيل: لتحفظه؛ لأنَّه كان أميًا، والأحسن الوقف على جملة واحدة، ثم تبتدئ بـ «كذلك»، فكذلك على الأول من قول المشركين، وعلى الثاني من قول الله (١)","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 25 AND "number" = 33), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"تَفْسِيرًا (٣٣)} [٣٣] تام؛ لعدم تعلق ما بعده؛ لأنَّه مبتدأ باتفاق، وخبره «أولئك» فلا يوقف على «جهنم»","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
