INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 25 AND "number" = 36), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"بِآَيَاتِنَا} [٣٦] حسن، لمن قرأ: «فدمرنَاهم»، وهي قراءة العامة (٢)؛ فعل ماض معطوف على محذوف، أي: فذهبا فبلغا الرسالة فكذبوهما، قال تعالى: فدمرناهم، أي: أدت الرسالة إلى دمارهم، وليس بوقف على قراءة من قرأ: [«فدمَّرنَّهم»] (٣) بالأمر وتشديد النون؛ لأنَّه كلام واحد، وهي قراءة عليّ - رضي الله عنه - وعنه أيضًا: «فدمِّرا بِهِم» بزيادة باء الجر بعد فعل الأمر (٤)، ونقل الزمخشري عنه أيضًا: «فَدَمَّرْتْهُمْ» بتاء المتكلم (٥)، وقرئ: «فَدَمَّرَانِهِمْ» بتخفيف النون (٦)، عزاها المرادي لبعضهم، ولم يذكرها السمين","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
