INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 26 AND "number" = 3), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"لأنَّ «إنْ» في موضع نصب بـ «باخع»، معناه: معنى الاستقبال؛ فكأنَّه قال: فظلت أعناقهم خاضعين أن أنزلنا عليهم آية، وإنَّما قال: خاضعين، ولم يقل: خاضعات؛ لأنَّه أراد بالأعناق: الجماعات والعرب، تقول: أتاني عنق من الناس، أي: جماعة، أو هو على حذف مضاف، أي: فظل أصحاب الأعناق، ثم حذف وبقي الخبر على ما كان عليه قبل حذف المخبر عنه مراعاة للمحذوف، أو أنَّه لما أضيف إلى العقلاء اكتسب منهم هذا الحكم كما اكتسب التأنيث بالإضافة للمؤنث في قوله: كما شرقت صدر القناة من الدم، إلى آخر ما قاله السمين. وليس «خاضعين» حالًا؛ لأنَّ الحال إنَّما يقع بعد تمام الكلام، وقوله: «فظلت أعناقهم لها» لم يتم إلَّا بما بعده","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
