INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 26 AND "number" = 10), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"لأنَّ الذي وقع به النداء لم يأت بعد، ومثله الوقف على «الظالمين»؛ لأنَّ «قوم فرعون» بدل من «القوم الظالمين» وبيان لهم، ولما كان «القوم الظالمين» يوهم الاشتراك، أزاله بعطف البيان؛ لأنَّه يوهم في المعنى، ولذلك عبر عن «الظالمين» بـ «قوم فرعون»، ووسموا: بالظلم؛ لأنَّهم ظلموا أنفسهم بالكفر","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
