INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 26 AND "number" = 11), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"للعدول عن الأمر إلى الاستفهام، وذلك موجب للوقف، ومن قرأ: «يتقون» بالتحتية (٢)؛ كان زيادة في الحسن، ومن قرأه بالتاء الفوقية (٣)؛ كان كلامًا واحدًا.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 26 AND "number" = 12), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"لمن قرأ: «ويضيقُ» و «ينطلقُ» بالرفع فيهما؛ على الاستئناف، أو عطفًا على أخاف؛ كأنَّه قال: إنَّي أخاف تكذيبهم إياي، ويضيق منه صدري، ولا ينطلق لساني، فالرفع يفيد ثلاث علل: ١ - خوف التكذيب. ٢ - وضيق الصدر. ٣ - وامتناع انطلاق اللسان. وليس بوقف لمن قرأ: بنصب القافين (٤)؛ عطفًا على «يكذبون».","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
