INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 26 AND "number" = 56), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"و «مقام كريم» يبنى الوقف على «كريم» على اختلاف المعربين في محل الكاف من كذلك، وفيها ثلاثة أوجه:١ - النصب بفعل مقدر، أي: أخرجنا آل فرعون من منازلهم كما وعدنا إيراثها بني إسرائيل.٢ - والجر على؛ أنَّها وصف لمقام، أي: ومقام كريم مثل ذلك المقام الذي كان لهم.٣ - والرفع؛ على أنَّها خبر مبتدأ محذوف، أي: الأمر كذلك؛ فإن كانت الكاف في محل رفع، أو في محل نصب، كان الوقف على «كذلك»؛ لأنَّ التشبيه وقع خبرًا، وهو تمام الفائدة فلا يقطع، وإن كانت في محل جر متصلة بما قبلها، كان الوقف على «كذلك» أيضًا حسنًا، دون «كريم»، وفي وجهي النصب والجر تشبيه الشيء بنفسه؛ لأنَّ المقام الذي كان لهم هو المقام الكريم، قال ابن لهيعة: هو القيوم، والمعنى: تركوا جناتهم وعيونهم وكنوزهم ومجالسهم وخرجوا في طلب موسى، والشرط في الوقفين، أعني: «كريم» و «كذلك» أن يجعل الضمير الأول، وهو: الواو في قوله: «فأتبعوهم» لموسى وأصحابه، والضمير الثاني، وهو: همٌّ لفرعون وأصحابه، أي: أنّ موسى وأصحابه تبعوا فرعون وأصحابه، حسن الوقف على «كذلك»، وليس «كريم»، ولا «كذلك» بوقف إن جعلت الواو في «فأتبعوهم» لفرعون وأصحابه، وهم ضمير موسى وأصحابه، أي: فتبع فرعون وأصحابه موسى؛ لأنَّ المعنى: خرجوا من","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
