INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 26 AND "number" = 192), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"{الْعَالَمِينَ (١٩٢)} [١٩٢] كاف؛ لمن قرأ: «نزّل» بالتشديد للزاي، ونصب (١): «الروحَ» مفعول (نزل) مبينًا للفاعل، وهو الله تعالى؛ لأنَّ (نزّل) المشدّد يقتضي التدريج والتنجيم بحسب المصالح؛ لأنَّه نزل إلى سما الدنيا جملة واحدة، ونجمه جبريل بأمر الله تعالى في عشرين سنة مخالفًا لقول الكفار لو كان من عند الله لنزل جملة واحدة (٢).قرأ ابن عامر وشعبة وحمزة والكسائي: «نَزّلَ» مشددًا، ومن قرأ: بتخفيف الزاي، ورفع: «الروحُ»، وهي قراءة الباقين كان جائزًا (٣)، وقرئ (٤): «نُزِّل» مشددًا مبنيًا للمفعول، و «الروحُ» نائب الفاعل، و «الأمينُ» صفته.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 26 AND "number" = 193), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"{الْأَمِينُ (١٩٣)} [١٩٣] ليس بوقف؛ لأنَّ الذي بعده ظرف للتنزيل، وكذا لا يوقف على «قلبك»؛ لأنَّ ما بعده علة في (التنزيل)، وكذا لا يوقف على «المنذرين»؛ لأنَّ ما بعده في موضع نصب؛ لأنَّه منذر بلسانه.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
