INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 26 AND "number" = 197), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"{آَيَةً} [١٩٧] ليس بوقف، سواء قرئ: «يكن» بالتحتية، أو بالفوقية، وسواء قرئ: بالرفع، أو بالنصب (٥)، ونصبها إما خبر «يكن»، و «أن يعلمه» اسمها، وكأنَّه قال: أو لم يكن لهم علم علماء بني إسرائيل آية لهم.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
