INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 26 AND "number" = 200), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"ومثله: «الأليم»، وقيل: لا يجوز؛ لأنَّ الفعل الذي بعد الفاء منصوب بالعطف على ما عملت فيه (حتى) والضمير في «سلكناه» للشرك، أو للكفر، أو للتكذيب، والضمير في «لا يؤمنون به» يعود على النبي - صلى الله عليه وسلم -، أي: كي لا يؤمنوا بمحمد - صلى الله عليه وسلم -، قاله النكزاوي. وكذا لا يوقف على «بغتة»؛ لأنَّ الذي بعدها جملة في موضع الحال","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
