INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 28 AND "number" = 35), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"إن علقت «بآياتنا»، بـ «يصلون»، وإن علقت بـ «الغالبون» كان الوقف على «إليكما»، ويبتدئ: «بآياتنا»؛ على «أنَّ» من ليست موصولة، أو موصولة، واتسع فيه والمعنى: أنتما ومن اتبعكما الغالبون بآياتنا، فـ «بآياتنا» داخل في الصلة تبيينًا، وهذا غير سديد؛ لأنَّ النحاة يمنعون التفريق بين الصلة والموصول؛ لأنَّ الصلة تمام الاسم؛ فكأنَّك قدمت بعض الاسم وأنت تنوي التأخير، وهذا لا يجوز، قاله الأخفش، ومحمد بن جرير؛ لأنَّ إضافة الغلبة إلى الآيات أولى من إضافة عدم الوصول إليها؛ لأنَّ المراد بالآيات: العصا وصفاتها، وقد غلبوا بها السحرة، وإنَّما يجوز ما قاله: لو كان «بآياتنا» غير داخل في الصلة، وتكون تبيينًا هذا في تقديم الصلة وتفريقها، وأما حذف الموصول وإبقاء صلته عوضًا عنه، ودليلًا عليه نحو: «إنَّ المصدِّقين والمصدِّقات وأقرضوا الله»، فهو سائغ كقول الشاعر:فَمَن يَهجو رَسولَ اللَهِ مِنكُم ... وَيَمدَحُهُ وَيَنصُرُهُ سَواءُ (٢)يريد ومن يمدحه وأيضًا يجوز الوقف على «إليكما»، ثم يبتدئ: «بآياتنا»؛ إن جعل «بآياتنا» قسمًا، وجوابه: «فلا يصلون» مقدمًا عليه، وردّ هذا أبو حيان وقال: جواب القسم لا تدخله الفاء، وإن جعل جوابه محذوفًا، أي: وحق آياتنا لتغلبن جاز، وقيل: متعلقة بـ «نجعل» أي: ونجعل لكما سلطانًا بآياتنا، وقيل: متعلقة بـ «يصلون»، وهو المشهور، وقيل: متعلقة، بمحذوف، أي: إذهبا بآياتنا، وضعف قول من قال: إنَّ في الآية تقديمًا وتأخيرًا، وإنَّ التقدير: ويجعل لكما سلطانًا بآياتنا فلا يصلون إليكما؛ لأنَّ لا يقع في كتاب الله إلَّا بتوقيف، أو بدليل قطعي، انظر: السمين.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
