INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 28 AND "number" = 67), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"ومثله: «ويختار» على أنَّ «ما» التي بعده نافية لنفي اختيار اختِيار الخلق لا اختيار الحق، أي: ليس لهم أن يختاروا بل الخيرة لله تعالى في أفعاله، وهو أعلم بوجوه الحكمة فيها، ليس لأحد من خلقه أن يختار عليه، قال أبو الحسن الشاذلي (٣): فر من مختاراتك كلها إلى الله تعالى، فإنَّ من اختار شيئًا لا يدري أيصل إليه أم لا؟ وإذا وصل إليه!! فلا يدري أيدوم له ذلك أم لا؟ وإذا دام إلى آخر عمره فلا يدري أفيه خير أم لا؟ فالخيرة فيما اختاره الله تعالى. والوقف على «ويختار»، وهو مذهب أهل السنة، وترك الوقف عليه مذهب المعتزلة، والطبري من أهل السنة منع أن تكون «ما» نافية، قال: لئلا يكون المعنى أنَّه لم تكن لهم الخبرة فيما مضى، وهي لهم فيما يستقبل، وهذا الذي قاله ابن جرير مروي عن ابن عباس، وليس بوقف إن جعلت «ما» موصولة في محل نصب","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
