INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 29 AND "number" = 24), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"كاف، هذا راجع إلى قصة إبراهيم، فإن قيل: ما معنى توسط هذه الآيات التي ليست من قصة إبراهيم؟ فالجواب أنَّها إنَّما توسطت على معنى: التحذير والتذكير؛ لأنَّهم كذبوا كما كذب قوم إبراهيم. قاله النكزاوي","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 29 AND "number" = 25), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"كاف، لمن قرأ: «مودةُ بينكم» بالرفع وحذف التنوين والإضافة خبر مبتدأ محذوف، أي: ذلك مودة بينكم، أو مبتدأ خبره «في الحياة الدنيا»، وبها قرأ عاصم وأبو عمرو والكسائي (١)، وليس بوقف لمن قرأها: بالرفع خبر «إنّ»، وجعل «ما» بمعنى: (الذي)، والتقدير: إنَّ الذين اتخذتموهم أوثانًا مودة بينكم، وكذا من نصب «مودةً» مفعولًا بالإتخاذ سواء أضاف، أو لم يضف، أي: إنَّما اتخذتموها مودة بينكم في الدنيا، وبالنصب قرأ: حمزة وحفص وحذف التنوين والإضافة (٢).","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
