INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 29 AND "number" = 66), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"{بِمَا آَتَيْنَاهُمْ} [٦٦] حسن؛ لمن سكن لام «وليتمتعوا»؛ على استئناف الأمر، بمعنى: التهديد، وبها قرأ ابن كثير وحمزة والكسائي، وليس بوقف لمن كسرها عطفًا على «ليكفروا» ويوقف على «وليتمتعوا» وبكسرها قرأ نافع وعاصم وابن عامر وأبو عمرو (١)، وهي محتملة لأن تكون لام الأمر أو (لام كي)، والمعنى: لا فائدة لهم في الإشراك إلَّا الكفر والتمتع","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
