INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 30 AND "number" = 15), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"يُحْبَرُونَ (١٥)، وقال ابن نصير: لا يوقف على أحد المتعادلين حتى يؤتى بالثاني، والأَوْلَى الفصل بين الفريقين، ولا يخلط أحدهما مع الآخر، ومعنى: «يحبرون»، قال ابن عباس: يكرمون، وقيل: يستمعون الغناء، وقيل: يتلذذون بكل ما يشتهون، قاله النكزاوي","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 30 AND "number" = 16), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"مُحْضَرُونَ (١٦)، ووقف بعضهم على «فسبحان الله»، ووسمه بالكافي، لمن قرأ في الشاذ (٣): «حينا تمسون وحينا تصبحون»، واستبعده أبو حاتم السجستاني، وأجازه غيره؛ كأنه ينبه على الاعتبار بصنع الله في جميع هذه الأوقات","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 30 AND "number" = 17), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"تُصْبِحُونَ (١٧)، لمن جعل التسبيح دعاء، كما فسّر ذلك ابن عباس، وفي الحديث: «من قال حين يصبح «فسبحان الله» إلى «تخرجون» أدرك ما فاته في يومه، ومن قالها حين يمسي أدرك ما فاته في ليلته» وليس بوقف لمن جعله الصلاة، أي: فصلوا لله حين تمسون صلاة المغرب وصلاة العشاء، وحين تصبحون صلاة الفجر، ثم قال: في التقديم «وعشيًّا»؛ يعني: صلاة العصر، «وحين","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
