INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 30 AND "number" = 41), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"عند أبي حاتم، قال: لأنَّ اللام في «ليذيقهم» لام قسم، وكانت مفتوحة، فلما حذفت النون للتخفيف، كسرت اللام فأشبهت (لام كي)، وخولف أبو حاتم في هذا: لأنَّ «ليذيقهم» متعلق بما قبله، فلا يقطع منه، وما قاله لا يجوز في العربية؛ لأنَّ لام القسم لا تكون مكسورة، قال بعضهم: ولا نعلم أن أحدًا من أهل العربية وافق أبا حاتم في هذا القول كما تقدم.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
