INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 30 AND "number" = 43), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"عند أبي حاتم؛ إن جعل موضع «يومئذ» نصبًا، وليس بوقف إن جعل موضعه رفعًا؛ على البدل من قوله: «يوم لا مردَّ له من الله»، وإنَّما فتح وهو في موضع رفع؛ لأنَّه أضيف إلى غير متمكن، فصار بمنزلة قول النابغة:عَلى حينَ عاتَبتُ المَشيبَ عَلى الصِبا ... وَقُلتُ أَلَمّا أَصحُ وَالشَيبُ وازِعُ (٢)وكقول الآخر:لم يمنع الشرب منها غير أن نطقت ... حمامة في غصون ذات أوقال (٣)فنصب «غير» وهو في موضع رفع؛ لأنَّ الظرف إذا أضيف لماض فالمختار بناؤه على الفتح كـ «يوم ولدته أمه»، وإنْ أضيف إلى جملة مضارعية كـ «هذا يوم ينفع الصادقين صدقهم»، أو اسمية كـ (جئت يوم زيد منطلق) فالإعراب أولى.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
