INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 31 AND "number" = 2), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"لمن قرأ (١): «وهدى ورحمةٌ» بالرفع بتقدير: هو هدى ورحمة، وليس بوقف لمن رفعه خبرًا ثانيًا، وجعل «تلك» مبتدأ، و «آيات» خبرًا، و «هدى ورحمة» خبرًا ثانيًا، نحو: الرمان حلو حامض، أي: اجتمع فيه الوصفان، وكذا ليس «الحكيم» بوقف إن نصب «هدى ورحمة» على الحال من «آيات».","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 31 AND "number" = 3), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"في محل «الذين يقيمون» الحركات الثلاث: الرفع والنصب والجر؛ فإنْ رفعت «الذين» بالابتداء، والخبر «أولئك» كان الوقف على (المحسنين) تامًا، وكذا إن نصب بتقدير: أعني، أو أمدح، وجائز: إن جرَّ صفة «للمحسنين»، أو بدلًا منهم، أو بيانًا.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
