INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 33 AND "number" = 50), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"هَاجَرْنَ مَعَكَ (٥٠) حسن؛ لأنَّ «وامرأةً» منصوب بمقدر، أي: ويحل لك امرأة، وليس بوقف إن عطف على مفعول «أحللنا لك»، «وامرأة» موصوفة بهذين الشرطين، وهما:١ - إن وهبت. ... ٢ - إن أراد النبي - صلى الله عليه وسلم -، ظاهر القصة يدل على عدم اشتراط تقدم الشرط الثاني على الأول؛ وذلك أنَّ إرادته -عليه الصلاة والسلام- للنكاح إنَّما هو مرتب على هبة المرأة نفسها له كما هو الواقع في القصة: لما وهبت، أراد نكاحها، ولم يرو أنَّه أراد نكاحها فوهبت، فالشرط الثاني مقدم معنى مؤخر لفظًا (٢).","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
