INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 34 AND "number" = 7), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"على استئناف ما بعده، وليس بوقف إن جعل ما بعده داخلًا فيما قبله؛ لأنَّ «إنكم» في تأويل المفتوحة، وإنما كسرت لدخول اللام في خبرها، وإلا فهي مفعول ثان لـ «ينبئكم».","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 34 AND "number" = 8), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"لانقضاء كلام الكفار للمسلمين على سبيل الاستهزاء والسخرية، والمعنى: ليس الرسول -عليه الصلاة والسلام- كما نسبتم، بل أنتم في عذاب النار، أو في عذاب الدنيا بما تكابدونه من إبطال الشرع، وهو يحق، وإطفاء نور الله، وهو يتم (١).","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
