ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 34 AND "number" = 10), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"ومثله: «والطير» على قراءة من قرأ: «والطيرُ» بالرفع، وهي قراءة الأعمش والسلمي، عطفًا على لفظ «جبال»، أو على الضمير في «أوَّبي»؛ كأنه قال: أوّبي أنت معه والطير، وأما من قرأ بالنصب، وهي قراءة الأمصار (٣)؛ فالنصب من ثلاثة أوجه، أحدها: أن يكون عطفًا على «فضلًا»؛ كأنه قال: آتينا داود منا فضلًا والطير، أي: وسخرنا له الطير، فعلى هذا لا يوقف على «فضلًا» الثاني؛ أن يكون معطوفًا على موضع: (يا جبال أوّبي مع الطير)؛ فعلى هذين الوجهين يوقف على «فضلًا».","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 34 AND "number" = 11), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"ومثله: «صالحًا».","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
