ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 34 AND "number" = 13), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"{كَالْجَوَابِ} [١٣] ليس بوقف؛ لأن قوله: «وقدور» مجرور عطفًا على «وجفان» وابن كثير يقف عليها بالياء، ويصل بها (١)، والجوابي، جمع: جابية، وهي: الحياض التي تجمع فيها المياه","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 34 AND "number" = 14), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"{مِنْسَأَتَهُ} [١٤] حسن، وهي: العصا كانت من شجرة نبتت في مصلاه، فقال: ما أنت؟ فقالت: أنا الخروبة نبت لخراب ملكك، فاتخذ منها عصا (٢)","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 34 AND "number" = 15), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"{آَيَةٌ} [١٥] حسن لمن رفع «جنتان»؛ على سؤال سائل؛ كأنه قيل: ما الآية، فقال: الآية جنتان، وليس بوقف إن جعل «جنتان» بدلًا من «آية»","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
