VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 34 AND "number" = 16), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"قال وهب بن منبه: بعث الله إليهم ثلاثة عشر نبيًا فكذبوهم، فأرسل الله عليهم سيل العرم. والعرم: الوادي، وقيل: السيل العظيم، وقيل: المطر الشديد (١).","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
