-- سورة يس (36) - 70 points
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 36 AND "number" = 1), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"إن جعل «يس» افتتاح السورة أو إسما لها ليس بوقف إن فُسّر «يس» بيا رجل أو يا إنسان؛ لأنَّ قوله: «إنك لمن المرسلين» قد دخل في الخطاب كأنه قال: يا محمد والقرآن الحكيم إنك لمن المرسلين، فيكون كالكلام الواحد، فلا يوقف على الحكيم؛ لأن قوله: «والقرآن الحكيم» قسم وجوابه: «إنك» فلا يفصل بين القسم وجوابه بالوقف.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 36 AND "number" = 3), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"على استئناف ما بعده وليس بوقف إن جعل خبرًا ثانيًا؛ لأن وكذا إن جعل موضع الجار والمجرور نصبًا مفعولًا ثانيًا لمعنى الفعل في المرسلين؛ لأن تقديره: إنك لمن الذين أرسلوا على صراط مستقيم، فيكون قوله: «على صراط مستقيم» داخلًا في الصلة، وكذا إن قدر: «إنك لمن المرسلين لتنذر قومًا» فيدخل قوله: «لتنذر» في الصلة أيضًا؛ فعلى هذه الأوجه لا يوقف على «المرسلين» ولا على «مستقيم».","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 36 AND "number" = 4), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"لمن قرأ: «تنزيلُ» بالرفع؛ خبر مبتدأ محذوف، أي: هو تنزيل؛ لأن القرآن قد جرى ذكره، وبالرفع قرأ نافع وابن كثير وأبو عمرو، والباقون بالنصب (١)، وكذا من قرأ: «تنزيلَ» بالنصب على المصدرية بفعل مضمر، أي: نزله تنزيل العزيز، أو نصب على المدح وهو في المعنى كالرفع، وليس بوقف إن جرّ «تنزيلِ» نعتًا للقرآن أو بدلًا منه، وبها قرأ أبو جعفر (٢).","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
