INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 36 AND "number" = 6), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"إن جعلت «ما» نافية، أي: لم تنذر قومًا ما أنذر آباؤهم؛ لأن قريشًا لم يبعث إليهم نبي قبل محمد - صلى الله عليه وسلم - وليس بوقف إن جعلت اسم موصول، والتقدير: لتنذر قومًا لذي أنذر آباؤهم","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
