INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 36 AND "number" = 12), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"؛ لأن قوله: «وآثارهم» معطوف على «ما» فكأنه قال: نكتب الشيء الذي قدموه وآثارهم، قيل: نزلت في قوم كانت منازلهم بعيدة عن مسجد رسول الله - صلى الله عليه وسلم - فكانت تلحقهم المشقة إذا أرادوا الصلاة مع النبي - صلى الله عليه وسلم - فأرادوا أن يتقربوا من مسجده فأنزل الله إنا نحن نحيي الموتى ونكتب ما قدموا وآثارهم. والوقف على «آثارهم» كاف؛ لأن «كل» منصوب بمقدر، أي: أحصينا كل شيء أحصيناه (٣).","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 36 AND "number" = 13), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"؛ لأن أصحاب القرية حال محل مثل الذي هو بيان مثل الذي في الآية فلا يفصل بينهما، أي: ومثل لهم مثلا مثل؛ فمثل الثاني بيان للأول، والأول مفعول به.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
