INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 36 AND "number" = 19), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"لمن قرأ (١): «أئن ذكرتم» على الاستفهام التوبيخي؛ لأن له صدر الكلام، سواء قرئ بهمزة محققة أو مسهلة، فكان شعبة ونافع وأبو عمرو يقرؤن (٢): «آن ذكرتم» بهمزة واحدة ممدودة، وقرأ عاصم ويحيى وحمزة والكسائي (٣): «إن ذكرتم» فعلى هذين القراءتين يحسن الوقف على «طائركم معكم»؛ لأن الاستفهام داخل على شرط، جوابه محذوف، تقديره: «آن ذكرتم» بهمزة ممدودة، «تطيركم» وأن الناصبة، أي: أتطيرتم لأن ذكرتم، وليس بوقف على قراءة زرّ بن حبيش (٤): «أأن ذكرتم» بهمزتين مفتوحتين، والتقدير: ألأن ذكرتم، واختلف سيبويه ويونس إذا اجتمع شرط واستفهام أيهما يجاب فذهب سيبويه إلى إجابة الاستفهام ويونس إلى إجابة الشرط، فالتقدير عند سيبويه: «آن ذكرتم تتطيرون»، وعند يونس: «تتطيروا» مجزوم؛ فالجواب على القولين محذوف، وهذا الوقف حقيق بأن يخص بتأليف، وهذا غاية في بيانه لمن تدبر،،، ولله الحمد","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
