VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 36 AND "number" = 38), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"وقرئ (١): «لا مستقرَّ» بـ «لا» النافية، وقرئ (٢): «لا مستقرٌ لها» بـ «لا» العاملة عمل «ليس» فـ «مستقرًا» اسمها و «لها» في محل نصب خبرها كقوله:تعز فلا شيء على الأرض باقيًا ... ولا وزر مما قضى الله واقيًا (٣)والمعنى: إنها لا مستقر لها في الدنيا، بل هي دائمة الجريان","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
