VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 36 AND "number" = 44), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"ومثله: «ترحمون» على أن جواب إذا محذوف، تقديره: وإذا قيل لهم هذا أعرضوا، ويدل عليه ما بعده، وهو: «وما تأتيهم من آية»، وليس بوقف إن جعل قوله: «إلا كانوا عنها معرضين» جواب، وإذا قيل لهم اتقوا، وجواب: وما تأتيهم من آية، إذ كل واحد منهما يطلب","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
