INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 36 AND "number" = 52), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"تام عند الأكثر، وقيل: الوقف على هذا إن جعل في محل جر صفة لـ «مرقدنا» أو بدلًا منه، وعليهما يكون الوقف على «هذا»، وقوله: «ما وعد الرحمن» خبر مبتدأ محذوف، أي: بعثكم ما وعد الرحمن، فـ «ما» في محل رفع خبر «بعثكم» أو: ما وعد الرحمن وصدق المرسلون حق عليكم، فهذا من كلام الملائكة، أو من كلام المؤمنين جوابًا لقول الكفار «من بعثنا من مرقدنا» ويؤيد هذا ما في (شرح الصدور) للسيوطي عن مجاهد قال: للكفار هجعة يجدون فيها طعم النوم قبل يوم القيامة، فإذا صيح بأهل القبور، يقول: الكافر ياويلنا من بعثنا من مرقدنا، فيقول: المؤمن إلى جنبه هذا ما وعد الرحمن وصدق المرسلون","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
