VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 36 AND "number" = 55), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"إن جعل «هم» مبتدأ، و «متكئُون» خبرًا لهم، والتقدير: هم وأزواجهم في ظلال متكئون على الأرائك، فقوله: «على الأرائك» متعلق به لا أنه خبر مقدم","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
