INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 36 AND "number" = 76), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"قَوْلُهُمْ عند الفراء وأبي حاتم؛ لانتهاء كلام الكفار، لئلا يصير: «إنا نعلم» مقول الكفار الذي يحزن النبي - صلى الله عليه وسلم -، والقراءة المتواترة كسر همزة «إنا نعلم»، وقول بعضهم من فتحها بطلت صلاته ويكفر فيه شيء، إذ يجوز أن يكون الخطاب للنبي - صلى الله عليه وسلم - مرادًا به غيره كقوله: «فلا تكونن ظهيرًا للكافرين»، «ولا تدع مع الله إلهًا آخر»، «ولا تكونن من المشركين» ولابد من التفصيل في التكفير إن اعتقد أن محمدًا - صلى الله عليه وسلم - يحزن لعلم الله بسِّر هؤلاء وعلانيتهم، فهذا كفر لا كلام فيه، وقد يكون فتحها على تقدير حذف لام التعليل، أو يكون «إنا نعلم» بدلًا من قولهم: أي ولا يحزنك إنا نعلم، وهذا يقتضي أنه قد نهي عن حزنه عن علم الله بسِّرهم وعلانيتهم، وليس هذا بكفر أيضًا تأمل (١).","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
