INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 37 AND "number" = 105), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"عند أبي حاتم، وجواب «فلما» قوله: «وناديناه» بجعل الواو زائدة، وقيل: جوابها محذوف، وقدَّره بعضهم بعد «الرؤيا» والواو ليست زائدة، أي: كان ما كان مما ينطق به الحال والوصف مما يدرك كنهه، وقيل تقديره: «فلما أسلما»، وقيل: جوابها «وتله» بجعل الواو زائدة، وعليه يحسن الوقف على «الجبين»، وقيل: نادته الملائكة من الجبل، أو كان من الأمر ما كان، أو قبلنا منه، أو همّ بذبحه عند أهل السنة لا أنه أمر السكين كما تقول المعتزلة، قيل: لما قال إبراهيم لولده إسماعيل إني أرى في المنام أني أذبحك، فقال: يا أبت هذا جزاء من نام عن حبيبه لو لم تنم ما أمرت بذلك. وقيل: لو كان في النوم خير لكان في الجنة","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
