INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 39 AND "number" = 19), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"والخبر محذوف، والمعنى: أفمن حق عليه كلمة العذاب، كمن وجبت له الجنة. فالآية على هذا جملتان ثم يبتدئ: «أفأنت تنقذ من في النار»، أي: أتستطيع أن تنقذ هذا الذي وجبت له النار، وليس بوقف إن جعل الخبر «أفأنت تنقذ» وعلى هذا فالوصل أولى، وإنما أعاد الاستفهام للتوكيد كما أعاد «أنَّ» في قوله: «أيعدكم أنكم إذا متم وكنتم ترابًا وعظامًا إنكم مخرجون» انتهى أبو العلاء الهمداني","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
