INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 39 AND "number" = 22), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"بإضمارٍ، أي: أفمن شرح الله صدره للإسلام كمن طبع على قلبه، أو كمن لم يشرح الله صدره، أوليس المنشرح صدره بتوحيد الله كالقاسي قلبه، فـ «من» مبتدأ وخبرها محذوف، وليس بوقف إن جعل «فويلٌ» دليلًا على جواب «أفمن» أي: كمن قسا قلبه فهو في ظلمة وعمى، بدليل قوله: «فويل للقاسية» (١)","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
