INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 41 AND "number" = 44), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"{فُصِّلَتْ آَيَاتُهُ} [٤٤] كاف، لمن قرأ: «أأعجمي» بهمزتين محققتين، وهم أبو بكر وحمزة والكسائي، وقرأ هشام بهمزة واحدة إخبارًا، والباقون بهمزة ومدة (١)، معناه: أكتاب أعجمي ورسول عربي، على وجه الإنكار لذلك، وليس بوقف لمن قرأ بهمزة واحدة بالقصر خبرًا (٢)؛ لأنَّه بدل من آياته، والمعنى على قراءته بالخبر: لقالوا هلا فصلت آياته، فكان منه عربي تعرفه العرب وأعجمي تعرفه العجم، وهو مرفوع خبر مبتدأ محذوف، أي: هو أعجمي، أو مبتدأ والخبر محذوف، أي: أعجمي وعربي يستويان، أو فاعل فعل محذوف، أي: يستوي أعجمي وعربي، وهذا ضعيف إذ لا يحذف بالفعل إلّا في مواضع (٣)","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
