-- سورة الزخرف (43) - 70 points
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 43 AND "number" = 2), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"إن جعل جواب القسم محذوفًا تقديره: لقد أوضحت الدليل وبينت لكم السبيل، أوحُمَّ الأمر، أي: قضى وقدّر، ومنه قول الأعشى:فَاِصبِري النَفسَ إِنَّ ما حُمَّ حَقٌّ ... لَيسَ لِلصَدعِ في الزُجاجِ اِتِّفاقُ (١)وقيل: (إن حم) إشارة الى اسمين من أسمائه تعالى كل حرف من اسم من باب الاكتفاء، والاكتفاء ببعض الكلمة معهود في العربية، وليس بوقف إن جعل جوابه: «إنا جعلناه» سواء جعل القسم «والكتاب» وحده، أو مع «حم» والأوّل يلزم منه محذور، وهو الجمع بين قسمين على مقسم واحد، وهم يكرهون ذلك، وإن جعل «حم» خبر مبتدأ محذوف، ثم تبتدئ مقسما بقوله: «والكتاب المبين» حسن الوقف على «حم» وسلمت من ذلك المحذور.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 43 AND "number" = 3), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"إن كان ما بعده خارجًا عن القسم؛ فإن جعل ما بعده وما قبله جواب المقسم به، لم يكن تامًا بل جائزًا؛ لكونه رأس آية.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
