INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 43 AND "number" = 33), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"{أُمَّةً وَاحِدَةً} [٣٣] ليس بوقف؛ لأن جواب: «لولا» لم يأت، وهو: «لجعلنا»، ومثله في عدم الوقف «من فضة»، و «يظهرون»، و «أبوابًا»، و «يتكئون» لأن العطف صيّرها كالشئ الواحد، والتام «وزخرفًا»، ومثله: «الحياة الدنيا»، وكذا «للمتقين».","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
