ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 43 AND "number" = 38), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"{الْمَشْرِقَيْنِ} [٣٨] حسن على القراءتين، أعنى: «جاءنا» بالإفراد، و «جاآنا» بالتثنية، فالذي قرأ بالإفراد أبو عمرو وحمزة الكسائي وحفص عن عاصم، وقرأ ابن كثير ونافع وابن عامر وأبو بكر عن عاصم: «جاآنا» بالتثنية، يعنى: الكافر وشيطانه (٢).","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 43 AND "number" = 39), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"لمن كسر همزة: «إنكم في العذاب»، وهو ابن ذكوان على الاستئناف (١)، وفاعل «ينفعكم» ضمير دل عليه قوله: «ياليت بيني وبينك بعد المشرقين»، وهو: التبرى، والتقدير: ولن ينفعكم اليوم تبرى بعضكم من بعض، وليس بوقف لمن قرأ: «أنكم» بفتح الهمزة (٢)؛ لأنه فاعل «ينفعكم» فلا يفصل منه، وقيل: فاعل «ينفعكم»، الإشراك، أي: ولن ينفعكم إشراككم في العذاب بالتأسى كما ينفع الاشتراك في مصائب الدنيا فيتأسى المصاب بمثله، ومنه قول الخنساء:وَلَولا كَثرَةُ الباكينَ حَولي ... عَلى إِخوانِهِم لَقَتَلتُ نَفسيوَما يَبكونَ مِثلَ أَخي وَلَكِن ... أُعَزّي النَفسَ عَنهُ بِالتَأَسّي (٣)أو فاعل «ينفعكم»، التمنى؛ أي: لن ينفعكم تمنيكم، أو لن ينفعكم اجتماعكم، أو ظلمكم، أو جحدكم.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
