-- سورة الدخان (44) - 45 points
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 44 AND "number" = 2), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"إن جعل جواب القسم «حم» مقدّمًا، وليس بوقف إن جعل جوابه: «إنا أنزلناه»، وإن جعل «والكتاب المبين» قسمًا كان الوقف على في «ليلة مباركة» تامًا، وإن جعل في «ليلة مباركة» صفة (للكتاب)، والقسم «حم» كان الجواب والوقف: «إنا كنا منذرين» ومنع بعضهم أن تكون «حم» قسمًا، والهاء راجعة الى «الكتاب»، وكأنه: أقسم على نفس المقسم عليه، وفسّر الشيء بنفسه، والأكثر على أن القسم واقع عليه.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 44 AND "number" = 4), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"إن نصب أمرًا بفعل مقدر، أو نصب على المصدر بتأويل العامل فيه إلى معناه، أي: أمرنا أمرًا بسبب الإنزال، أو نصب على الاختصاص، وليس المراد الاختصاص الاصطلاحى فإنه لا يكون نكرة، أعني: بهذا الأمر أمرًا خاصًا وليس بوقف ان نصب بـ «يفرق» أو نصب على معنى: يفرق، أي: فرقًا الذي هو مصدر: يفرق؛ لأنه إذا حكم بشيء وكتبه فقد أمر به، أو نصب على الحال من «كل» المضافة والمسّوغ عام؛ لأن كل من صيغ العموم، أو حالًا من أمر فهو خاص لوصفه بـ «حكيم» وفيه مجئ الحال من المضاف إليه في غير المواضع المذكورة، أو نصب حالًا من الضمير في «حكيم» أو نصب على إنه مفعول «منذرين»، والمفعول الأول محذوف، أي: منذرين الناس أمرًا، أو نصب من ضمير الفاعل في «أنزلناه»، أو من ضمير المفعول وهو الهاء في «أنزلناه»، أي: آمرين به أمرًا أو مأمورًا به، أو نصب على إنه مفعول له، والعامل فيه «أنزلناه» وحينئذ لا يحسن الوقف على شيء من قوله: «إنا أنزلناه» إلى هذا الموضع.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 44 AND "number" = 5), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"ومثله: «إنا كنا مرسلين»؛ إن نصب «رحمة» بفعل مقدّر، وليس بوقف إن نصب «رحمة» من حيث ينتصب أمرًا من الحال والمفعول له، ولم يحسن الوقف من قوله: «إنا أنزلناه» إلى هذا الموضع.سمى الله تعالى إرسال الرسل «رحمة»، أي: رحمة لمن أطاعهم، وقال سعيد بن جبير: اللفظ عام للمؤمن والكافر، فالمؤمن قد سعد به، والكافر بتأخير العذاب عنه، وعلى هذا لا يوقف على «مرسلين».","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
