-- سورة الذاريات (51) - 42 points
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 51 AND "number" = 4), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"وهو: تام، وحكي عن سيبويه أنَّه سأل الخليل بن أحمد لِمَ لَمْ تكن الواو التي بعد واو القسم كواو القسم؟ فأجابه بقوله: لو كانت قسمًا لكان لكل واحدة من الواوات جواب، فلذلك صارت هذه الأشياء قسمًا في أوائل السور وإن طال النسق، فلو قلت: والله لا أكلم زيدًا غدًا ولا أرافقه ولا أشاركه ولا أبيعه، من غير إعادة لفظ الجلالة، ثم فعلت جميع ذلك، فكفارة واحدة بالفعل الأوَّل، ولا شيء عليك فيما بعده؛ لأنَّ المعطوف على القسم من غير إعادة لفظ الجلالة غير قسم، وشرط التمام في «لصادق» أن يجعل ما بعده مستقبلًا، وليس بوقف إن عطف على ما قبله وداخلًا في الجواب، ومن تتمته لأنَّ شأن القسم إذا ابتدئ به لابدَّ أن يكون له جواب، وأما لو توسط نحو: ضرب والله زيد، أو تأخر نحو: ضرب زيدٌ عمرًا والله، فلا يحتاج إلى جواب.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 51 AND "number" = 6), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"تام؛ إن جعل ما بعده مستأنفًا قسمًا ثانيًا، فيكون قد أقسم: بالذَّاريات فالحاملات فالجاريات فالمقسمات، فجعل مجموعها قسمًا واحدًا، وفصّل أبو حيان حيث قال: والَّذي يظهر أنَّ المقسم به شيئان، فإنَّ العطف بالواو أشعر بالتغاير، وإن جاء بالفاء، دل على أنَّها لموصوف واحد كقوله: «والعاديات ضبحًا * فالموريات قدحًا * فالمغيرات صبحًا» فهي راجعة إلى «العاديات»، وهي: الخيل، انظره في المرسلات. وليس بوقف إن جعل ما بعده داخلًا في جواب القسم، والقسم الثاني في قوله: «والسماء ذات الحبك» وجوابه: «إنَّكم لفي قول مختلف»","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
