INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 51 AND "number" = 11), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"ليس بوقف؛ لأنَّ «يسألون» صفة «الذين» و «أيَّان يوم الدين» مبتدأ وخبران، قيل: هما ظرفان فكيف يقع أحد الظرفين في الآخر؟ أجيب بأنَّه على حذف مضاف أي: «أيَّان»؛ وقوع يوم الدين، قاله السمين.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 51 AND "number" = 12), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"كاف؛ لأنَّ «يوم» مبتدأ، و «هم» خبره، وقيل: ليس بوقف؛ لأنَّ «يوم» في موضع رفع إلّا أنَّه مبني على الفتح، وهو بدل من قوله: «يوم الدين»، وقرأ ابن أبي عبلة (١): «يَوْمُ هُمْ» بالرفع، ويؤيد بالقول بالبدلية، ورسموا: «يوم هم» كلمتين، «يوم» وحدها كلمة و «هم» وحدها كلمة","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
