INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 51 AND "number" = 23), 0, 'BOOKS', 'APPROVED', '{"ruling":"ليس بوقف","explanation":"على قراءة من قرأ: «مثلُ» بالرفع؛ لأنَّ «مثل» نعت «لحق»؛ كأنَّه قال: حق مثل نطقكم، وبهذه القراءة قرأ حمزة والكسائي، وقرأ ابن كثير ونافع وأبو عمرو وابن عامر وحفص: «مثلَ ما» بنصب «مثلَ» (١)؛ على الحال من الضمير في «لحق»، أو حال من نفس حق، أو هي حركة بناء لما أضيف إلى مبنى بنى كما بنيت (غير) في قوله:لم يمنع الشرب منها غير أنْ نطقت ... حمامة في غصون ذات أوقال (٢)","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 51 AND "number" = 24), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"إن نصب «إذ» بمقدر، وليس بوقف إن نصب بحديث بتقدير: هل أتاك حديثهم الواقع في وقت دخولهم عليه، ولا يجوز نصبه بـ (أتاك) لاختلاف الزمانين، وقرأ العامة (٣): «المكرَمين» بالتخفيف، وعكرمة (٤): بالتشديد ونصب «سلامًا»، بتقدير: فعل، أي: سلمنا سلامًا، أو هو نعت لمصدر محذوف، أي فقالوا: قولًا سلامًا، لا بالقول؛ لأنَّه لا ينصب (إلّا) بثلاثة أشياء الجمل، نحو: «قال إنِّي عبد الله»، والمفرد المراد به لفظه نحو: يقال له إبراهيم، والمفرد المراد به الجملة نحو: قلت قصيدة وشعرًا، ورفع «سلام» بتقدير: عليكم سلام.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
