VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 51 AND "number" = 52), 0, 'BOOKS', 'APPROVED', '{"ruling":"أكفى","explanation":"فالكاف في محل رفع، أي: الأمر كذلك، فالتشبيه من تمام الكلام، فالكاف خبر مبتدأ محذوف، أو في محل نصب، أي: مثل تكذيب قومك إياك مثل تكذيب الأمم السابقة لأنبيائهم، ولا يجوز نصب الكاف بـ «أتي»؛ لأنَّها ليست متصلة بشيء بعدها؛ لأنَّ «ما» إذا كانت نافية لم يعمل ما بعدها في شيء قبلها، ولو أتى موضع «ما» بـ (لم) لجاز أن تنصب الكاف بـ «أتي»؛ لأنَّ المعنى يسوغ عليه، والتقدير: كذبت قريش تكذيبًا مثل تكذيب الأمم السابقة رسلهم (٢).","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
