INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 53 AND "number" = 37), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"وَإِبْرَاهِيمَ الَّذِي وَفَّى (٣٧) كاف؛ على استئناف سؤال كأنَّ قائلًا قال: وما في صحفهما؟ فأجيب ألّا تزر وازرة وزر أخرى، وجائز: إن جعل ما بعده بدلًا من «ما» في قوله: «بما في صحف»، وكذا لا وقف إن جعل ما بعده في محل نصب، والعامل فيه «ينبأ»؛ فعلى هذين التقديرين لا يوقف على «وفّي»","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
