INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 53 AND "number" = 61), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"أي: لاهون، وقيل: الحزين، والسمود بلغة حمير: الغناء، يقول: الرجل للمرأة اسمدي لنا، أي: غنِّي لنا، ونزل جبريل يومًا وعند الرسول رجل يبكي، فقال: له من هذا الرجل، فقال: فلان، فقال: جبريل إنَّا نزن أعمال بني آدم كلها إلّا البكاء، فإنَّ الله يطفىء بالدمعة بحورًا من نار جهنم.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
