INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 54 AND "number" = 6), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"تام عند أبي حاتم، ولا يجوز وصله؛ لأنَّه لو وصل بما بعده صار «يوم يدع» ظرفًا للتولي عنهم، وليس كذلك بل هو ظرف «يخرجون»، والمعنى عندهم: على التقديم والتأخير، أي: يخرجون من الأجداث يوم يدع الدَّاع، فإذا كان كذلك فالتام «فتول عنهم»؛ لأنَّ الظرف إذا تعلق بشيء قبله لم يوقف على ما قبله، فلا يوقف على «شيءٍ نُكُر» وكذا لا يوقف على «أبصارهم»؛ لأنَّ «خاشعًا»، أو «خشعًا» (٢)، منصوب على الحال من الضمير في «يخرجون»، أي: يخرجون خشعًا أبصارهم يوم يدع الداع، وكذا «منتشر»؛ لأنَّ قوله: «مهطعين» منصوب على الحال من فاعل «يخرجون» فهي حال متداخلة","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
