INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 54 AND "number" = 47), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"إن نصب «يوم يذوقوا» على التقديم والتأخير، أي: يقال لهم ذوقوا مس سقر يوم يسحبون، وليس «يوم» ظرف (إضلالهم)؛ فإن جعل الظرف متعلقًا بما قبله ومتصلًا به لم يوقف على «سُعُر»","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
