INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 54 AND "number" = 49), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"ونصب «كل» على الاشتغال، والنصب أولى لدلالته على عموم الخلق، والرفع لا يدل على عمومه، قال: أهل الزيغ إن ثَم مخلوقات لغير الله تعالى، فرفع «كل» يوهم مالا يجوز، وذلك إنه إذا رفع «كل» كان مبتدأ، و «خلقناه» صفة لـ «كل»، أو لـ «شيء» و «بقدر» خبر، وحينئذ يكون له مفهوم لا يخفى على متأمله؛ لأنَّ «خلقناه» صفة، وهي قيد فيفيد أنَّه إذا انتفى فيلزم أن يكون الشيء الذي ليس مخلوقًا لله لابقدر، راجع السمين","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 54 AND "number" = 50), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"ومثله: «من مُدّكِر»، وكذا «في الزبر»، و «فعلوه» صفة، والصفة لا تعمل في الموصوف، ومن ثَم لم يجز تسليط العامل على ما قبله، إذ لو صح لكان تقديره: فعلوا كل شيء في الزبر، وهو باطل، فرفع «كل» واجب على الابتداء، وجملة «فعلوه» في موضع رفع صفة لـ «كل» وفي موضع جر صفة لـ «شيء» وفي «الزبر» خبر «كل»، والمعنى: وكل شيء مفعول ثابت في الزبر، أي: في الكتب، وكذا «مستطر»","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
