INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 55 AND "number" = 11), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"والأكمام جمع: كِم بالكسر، والكم: وعاء الثمرة، وهو كاف لمن قرأ: «والحب ذا العصف والريحان» بالنصب وهي قراءة ابن عامر وأهل الشام؛ لأنَّ «والحب» ينتصب بفعل مقدر؛ كأنَّه قال: وخلق فيها الحب ذا العصف والريحان والعصف التبن، وليس «الأكمام» بوقف لمن قرأ: «والحب ذو العصف والريحان» بالرفع، وكان وقفه على «والريحان» وهو تام سواء قرئ: بالرفع أو بالنصب أو بالجر","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 55 AND "number" = 13), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"تام، ومثله في جميع ما يأتي، وكذا يقال: فيما قبله إلَّا ما استثني يأتي التنبيه عليه.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
