INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 55 AND "number" = 14), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"كاف؛ على استئناف ما بعده، وليس بوقف إن عطف على ما قبله، إلَّا أن يجعل من عطف الجمل، فيكفي الوقف على ما قبله وكذا: «من نار».","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
