INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 55 AND "number" = 16), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"تام، إن رفع «ربُّ» على الابتداء، وكاف إن رفع بإضمار مبتدأ، وليس بوقف إن رفع بدلًا من الضمير في «خلق»، ومثله في عدم الوقف إن جرَّ بدلًا أو بيانًا من «ربكما»، وبها قرأ ابن أبي عبلة (١)، فلا يفصل بين البدل والمبدل منه بالوقف لأنَّهما كالشيء الواحد.","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
