INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 55 AND "number" = 24), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"كاف، ومثله: «تكذبان»، «وفان» الأولى، وصله حكي عن الشعبي أنَّه قال: إذا قرأت كل من عليها فان، فلا تقف حتى تقول «ويبقى وجه ربك ذو الجلال والإكرام». قاله عيسى بن عمر؛ لأنَّ تمام الكلام في الإخبار عن بقاء الحق سبحانه وتعالى بعد فناء خلقه، فإن قيل: أي، نعمة في قوله: «كل يوم هو في شأن»، قيل: الانتقال من دار الهموم إلى دار السرور (٢).","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
