INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 55 AND "number" = 29), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"تام عند أبي حاتم، ثم يبتدئ: «كل يوم هو في شأن»، وقال الأخفش: التَّام على «شأن». وقال يعقوب: التَّام «كل يوم»، ثم يبتدئ: «هو في شأن» قال أبو جعفر: أما قول يعقوب، فهو مخالف لقول الذين شاهدوا التنزيل؛ لأنَّ ابن عباس قال: خلق الله لوحًا محفوظًا ينظر فيه كل يوم ثلاثمائة وستين نظرة. فهذا يدل على أنَّ التام: «كل يوم هو في شأن»، غير أنَّ قول يعقوب قد روى نحوه عن أبي نهيك قال: يسأله من في السموات والأرض كل يوم وربنا في شأن. وأما قول الأخفش إنَّ التامّ على «شأن» فصحيح على قراءة من قرأ: «سنفرُغ» بالنون والراء مضمومة وبها قرأ الأخوان، أو على ما قرئ شاذًا: «سيُفرَغ» بضم الياء وفتح الراء (٣)، وأما من قرأ: «سيَفرُغ» بفتح","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
