-- سورة الواقعة (56) - 43 points
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 56 AND "number" = 2), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"لمن قرأ ما بعده بالرفع خبر مبتدأ محذوف، ولم تعلق «إذا رجَّت» بـ «وقعت»، وإلَّا بأن علق «إذا رجَّت» بـ «وقعت» كان المعنى: وقت وقوع الواقعة خافضة رافعة، هو: وقت رجِّ الأرض، فلا يوقف على «كاذبة»، وكذا إذا أعربت «إذًا» الثانية بدلًا من الأولى، وليس بوقف أيضًا لمن قرأ: «خافضة رافعة» بالنصب (١)؛ على الحال من «الواقعة»، أي: خافضة لقوم بأفعالهم السيئة إلى النار، ورافعة لقوم بأفعالهم الحسنة إلى الجنة، ومثله في عدم الوقف أيضًا إذا أعربت «إذًا» الأولى مبتدأ، و «إذًا» الثانية خبرها في قراءة من نصب «خافضة رافعة»، أي: إذا وقعت الواقعة خافضة رافعة في هذه الحالة ليس لوقعتها كاذبة، وكاف لمن نصب «خافضة رافعة» على المدح بفعل مقدَّر كما تقول: جاءني عبد الله العاقل وأنت تمدحه، وكلمني زيد الفاسق تذمه","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 56 AND "number" = 3), 0, 'BOOKS', 'APPROVED', '{"ruling":"جائز","explanation":"على القراءتين، أعني رفع: «خافضة رافعة» ونصبهما، و «إذا» الأولى شرطية، وجوابها الجملة المصدرة بـ «ليس»، أو جوابها محذوف، تقديره: إذا وقعت الواقعة كان كيت وكيت","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 56 AND "number" = 7), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"وقيل: كاف، ثم فسَّر «الثلاثة» فقال: «فأصحاب الميمنة ما أصحاب الميمنة»، كأنَّه يعظم أمرهم في الخير، وأجاز أبو حاتم تبعًا لأهل الكوفة أن تكون «ما» صلة، فكأنَّه قال: فأصحاب الميمنة أصحاب الميمنة، كما قال: «والسابقون السابقون»، وذلك غلط بيِّن؛ لأنَّه كلام لا","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
