INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 56 AND "number" = 16), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"على استئناف ما بعده وليس بوقف إن جعل حالًا","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
