INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 56 AND "number" = 21), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"لمن قرأ: «وحور عين» بالرفع، أي: وعندهم حور، أو: ولهم حور عين، وهي قراءة ابن كثير ونافع وعاصم وأبي عمرو وابن عامر (٢)؛ لأنَّ: الحور العين لا يطاف بهنَّ، ومثله في الحسن الوقف على «يشتهون» على قراءة أُبيّ بن كعب: «وحورًا عينًا» بالنصب (٣)؛ بمعنى: ويزوّجون حورًا عينًا، وليس «يشتهون» وقفًا لمن قرأ: «وحور» بالجرّ عطفًا على «بأكواب","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
