INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 58 AND "number" = 22), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"حسن، نزلت هذه الآية في أبي عبيدة عامر بن الجراح: لما قتل أباه حين تعرض له يوم بدر فأعرض عنه فلازمه فلما أكثر عليه قتله، وفي أبي بكر الصديق: دعا أباه إلى البراز يوم بدر، وفي مصعب بن عمير: قتل أخاه يوم أُحد، وفي عمر بن الخطاب: قتل خاله العاصي بن هشام يوم بدر، وفي علي وحمزة: قتلا الوليد وشيبة يوم بدر، بدأ أولًا بالآباء؛ لأنَّ الواجب على الأولاد طاعتهم فنهاهم عن توادهم ثم ثنَّى بالأبناء ثم ثلَّث بالإخوان ثم ربَّع بالعشيرة، والمعنى: لا توادوا الكفار ولو كانوا آباءكم، كأبي عبيدة عامر بن الجراح، وأبي بكر الصديق، أو إخوانكم كمصعب بن عمير، أو عشيرتكم كعمر وعلي وحمزة","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;

