INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 61 AND "number" = 10), 0, 'BOOKS', 'APPROVED', '{"ruling":"كاف","explanation":"كاف، إن جعل «تؤمنون» خبر مبتدأ محذوف، أي: تلك التجارة هي تؤمنون، فالخبر نفس المبتدأ، فلا يحتاج لرابط، وكذا إن جعل «تؤمنون» بمعنى: آمنوا، بمعنى الأمر؛ لأنَّ بعده «يغفر» مجزوم على جواب الأمر، ونظير ذلك قول العرب: اتقي الله امرؤ فعل خيرًا يثب عليه، معناه: ليتق الله، فانجزم قوله: يثب، على تقدير: هذا الأمر فكذلك انجزم «يغفر» على تقدير: آمنوا وجاهدوا، وليس «أليم» بوقف إن جعل «تؤمنون»، بمعنى: أن تؤمنوا، فهو منصوب المحل تفسيرًا للتجارة، فلما حذف أن ارتفع الفعل كقوله:ألا أيهذا الزاجري أحضر الوغى (٢)الأصل إن أحضر، فكأنَّه قال: هل أدلكم على تجارة منجية إيمان وجهاد، وهو معنى حسن لولا ما فيه من التأويل. قاله المبرد، وعليه فلا يوقف من قوله: «تؤمنون» إلى قوله: «في جنات عدن»؛ لأن «يغفر» مجزوم على جواب الأمر فلا يفصل بين الأمر وجوابه بالوقف، وقال الفراء: هو مجزوم على جواب الاستفهام، وهو قوله: «هل أدلكم»، واختلف الناس في تصحيح هذا القول فبعضهم غلطة قال الزجاج: ليسوا إذا دلهم على ما ينفعهم يغفر لهم إنما يغفر لهم إذا آمنوا وجاهدوا، يعني: أنَّه ليس مرتبًا على مجرد الاستفهام ولا مجرد الدلالة ويجوز أنَّ الفراء نظر إلى المعنى؛ لأنَّه قال: هل أدلكم على تجارة، ثم فسّر التجارة بقوله: «تؤمنون» فكأن الاستفهام إنَّما وقع على نفس المفسّر؛ كأنَّه قال: هل","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
