VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 62 AND "number" = 11), 0, 'BOOKS', 'APPROVED', '{"ruling":"حسن","explanation":"وقال محمد بن عيسى تام، قال مقاتل والحسن: أصاب المدينة جوع وغلاء فقدم دحية بن خليفة الكلبي بتجارة وزيت من الشام وكان إذا قدم قدم بكل ما يحتاج إليه من البر وغيره فضرب الطبل ليؤذن الناس بقدومه، والنبي - صلى الله عليه وسلم - يخطب يوم الجمعة فخرجوا إليه، ولم يبق مع النبي - صلى الله عليه وسلم - في المسجد إلَّا اثنا عشر رجلًا وامرأة منهم أبو بكر الصديق وعمر، فقال النبي: - صلى الله عليه وسلم - كم بقي في المسجد، فقالوا اثنا عشر رجلًا وامرأة، فقال النبي: - صلى الله عليه وسلم - لولا هؤلاء القوم لسوَّمت عليهم الحجارة من السماء، وفي لفظٍ: والذي نفس محمد بيده لو تتابعتم حتى لم يبق منكم أحد لسال بكم الوادي نارًا (٢)","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;

