VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 68 AND "number" = 32), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"لأنَّه آخر القصة، وأتم منه: «كذلك العذاب» وهو قول نافع وأبي حاتم، والظاهر أنَّ أصحاب الجنة كانوا مؤمنين أصابوا معصية وتابوا، والإشارة بكذلك إلى العذاب الذي نزل بالجنة، أي: كذلك العذاب الذي نزل بقريش بغتة، فالتشبيه تمام الكلام ثم تبتدئ: «ولعذاب الآخرة أكبر»","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
