INSERT INTO "WaqfPoint" ("ayahId", "wordIndex", "methodology", "status", "data")
VALUES ((SELECT id FROM "Ayah" WHERE "surahNumber" = 70 AND "number" = 35), 0, 'BOOKS', 'APPROVED', '{"ruling":"تام","explanation":"وتقدم أن رسم «فما لهؤلاء القوم» في النساء و «مال هذا الكتاب» في الكهف و «مال هذا الرسول» في الفرقان و «فمال الذين كفروا» هنا كلمتان «ما» كلمة و «ل» كلمة، وقف أبو عمرو على «ما» والكسائي بخلاف عنه، والباقون على «اللام»، وقال ابن الجزري: اختار الوقف على «مال» كل القراء، فمن وقف على «ما» ابتدأ بما بعدها، ومن وقف على «اللام» ابتدأ بما بعدها، واتفقوا على كتابة اللام منفصلة، وتقدم ما يغني عن إعادته، وإنَّما أعدته للإيضاح","source":"Manar al-Huda (Ashmuni)","hukumIbtida":"جائز","taalil":""}')
ON CONFLICT DO NOTHING;
